_CLAUDE_RETRY_DELAYS = (3, 8, 15, 30, 60)
CLAUDE_MODEL = os.environ.get("ANTHROPIC_MODEL", "claude-sonnet-4-6")


def _is_transient_api_error(exc: Exception) -> bool:
    s = str(exc).lower()
    return any(
        token in s
        for token in ("529", "overloaded", "rate_limit", "rate limit", "503", "timeout", "temporarily unavailable")
    )


def claude_messages_create(**kwargs):
    """Retry Anthropic calls on transient overload / rate-limit errors."""
    kwargs["model"] = CLAUDE_MODEL
    last_exc = None
    for attempt, delay in enumerate(_CLAUDE_RETRY_DELAYS):
        try:
            return claude_client.messages.create(**kwargs)
        except Exception as exc:
            last_exc = exc
            if not _is_transient_api_error(exc) or attempt >= len(_CLAUDE_RETRY_DELAYS) - 1:
                raise
            print(f"  ⏳ Claude overloaded — retry in {delay}s ({attempt + 1}/{len(_CLAUDE_RETRY_DELAYS) - 1})…")
            time.sleep(delay)
    raise last_exc


BLOCK_LOG_PATH = "/tmp/sunnomad_blocked.jsonl"


def _parse_block_meta(error) -> dict:
    """Extract moderation categories / stage / reason from OpenAI or BFL errors."""
    import json as _json
    import re as _re

    meta = {
        "block_reason": "",
        "categories": [],
        "moderation_stage": "",
        "error_code": "",
        "error_type": type(error).__name__ if not isinstance(error, str) else "str",
    }
    body = None
    resp = getattr(error, "response", None)
    if resp is not None:
        try:
            body = resp.json()
        except Exception:
            try:
                body = _json.loads(getattr(resp, "text", "") or "")
            except Exception:
                body = None
    if isinstance(body, dict):
        err = body.get("error") or body
        if isinstance(err, dict):
            md = err.get("moderation_details") or {}
            cats = md.get("categories") or err.get("categories") or []
            if isinstance(cats, str):
                cats = [cats]
            meta["categories"] = [str(c).strip() for c in cats if str(c).strip()]
            meta["moderation_stage"] = str(md.get("moderation_stage") or "")
            meta["error_code"] = str(err.get("code") or "")
            msg = str(err.get("message") or "")
            sv = _re.search(r"safety_violations=\[([^\]]*)\]", msg)
            if sv and not meta["categories"]:
                meta["categories"] = [
                    c.strip().strip("'\"") for c in sv.group(1).split(",") if c.strip()
                ]
    s = str(error)
    if not meta["categories"]:
        sv = _re.search(r"safety_violations=\[([^\]]*)\]", s)
        if sv:
            meta["categories"] = [
                c.strip().strip("'\"") for c in sv.group(1).split(",") if c.strip()
            ]
        else:
            cm = _re.search(r"['\"]categories['\"]\s*:\s*\[([^\]]*)\]", s)
            if cm:
                meta["categories"] = [
                    c.strip().strip("'\"") for c in cm.group(1).split(",") if c.strip()
                ]
    if not meta["moderation_stage"]:
        sm = _re.search(r"moderation_stage['\"]?\s*[:=]\s*['\"]?(\w+)", s)
        if sm:
            meta["moderation_stage"] = sm.group(1)
    if meta["categories"]:
        meta["block_reason"] = ",".join(meta["categories"])
    elif meta["error_code"]:
        meta["block_reason"] = meta["error_code"]
    elif "content moderated" in s.lower() or "request moderated" in s.lower():
        meta["block_reason"] = "content_moderated"
    elif "sexual" in s.lower():
        meta["block_reason"] = "sexual"
    elif "safety" in s.lower() or "moderation" in s.lower():
        meta["block_reason"] = "safety/moderation"
    else:
        meta["block_reason"] = "error"
    return meta


def log_blocked(
    place: dict | None,
    character_key: str,
    shot_type: str,
    shot_category: str,
    prompt: str,
    error,
    *,
    event: str = "blocked",
    attempt: int = 1,
    recovered: bool | None = None,
):
    """Log blocked/failed generations (+ soft retries) for later analysis → BLOCK_LOG_PATH."""
    import json as _json
    from datetime import datetime as _dt

    place = place or {}
    meta = _parse_block_meta(error)
    entry = {
        "ts": _dt.now().isoformat(),
        "event": event,  # blocked | soft_retry | soft_retry2 | failed
        "attempt": attempt,
        "recovered": recovered,
        "place": place.get("name_en", ""),
        "country": place.get("country_code", ""),
        "terrain": place.get("terrain_type", ""),
        "place_type": place.get("place_type", ""),
        "character": character_key,
        "shot_type": shot_type,
        "shot_category": shot_category,
        "spiciness": SPICINESS.get(shot_type, "n/a") if shot_type in SPICINESS else "n/a",
        "block_reason": meta["block_reason"],
        "categories": meta["categories"],
        "moderation_stage": meta["moderation_stage"],
        "error_code": meta["error_code"],
        "error_type": meta["error_type"],
        "error": str(error)[:400],
        "prompt_excerpt": (prompt or "")[:500],
    }
    try:
        with open(BLOCK_LOG_PATH, "a") as _f:
            _f.write(_json.dumps(entry, ensure_ascii=False) + "\n")
    except OSError as _oe:
        print(f"  ⚠️  block log write failed: {_oe}")
    cats = ",".join(meta["categories"]) if meta["categories"] else "-"
    stage = meta["moderation_stage"] or "-"
    rec = ""
    if recovered is True:
        rec = " recovered=yes"
    elif recovered is False:
        rec = " recovered=no"
    print(
        f"  🚫 {event} [{shot_category}/{shot_type}] "
        f"reason={meta['block_reason'] or '?'} cats={cats} stage={stage} "
        f"char={character_key} place={place.get('name_en', '')}{rec} "
        f"→ {BLOCK_LOG_PATH}"
    )

