def is_bookstore_place(place: dict | None) -> bool:
    """Literary / university / known book-town energy — Port Angeles etc."""
    if not place:
        return False
    name = _place_name_en(place)
    if name in BOOKSTORE_INTELLECTUAL_PLACES:
        return True
    nl = name.lower()
    return any(h in nl for h in _BOOKSTORE_NAME_HINTS)


