def get_cinema_local_film_note(place: dict) -> str:
    """Prefer ≥1 local-production title on the cinema program board."""
    name = _place_name_en(place)
    films = LOCAL_CINEMA_FILMS_BY_PLACE.get(name)
    if not films:
        nl = name.lower()
        for key, titles in LOCAL_CINEMA_FILMS_BY_PLACE.items():
            if key.lower() in nl or nl in key.lower():
                films = titles
                break
    cc = (place.get("country_code") or "").upper()
    if not films:
        films = LOCAL_CINEMA_FILMS_BY_COUNTRY.get(cc)
    if films:
        pick = random.choice(films)
        return (
            f"LOCAL FILM (MANDATORY): At least one readable poster or program title is a "
            f"{cc or 'local'} production — use \"{pick}\" (or clearly the same title, hand-lettered/marquee ok). "
            "Other arthouse titles may sit beside it. NOT a board of only US blockbusters."
        )
    return (
        f"LOCAL FILM (MANDATORY): At least one readable poster/program title from a film "
        f"produced in {cc or 'this country'} — local cinema culture, not only Hollywood."
    )


