def zara_shore_coverup_needed(place: dict | None, activity_key: str | None = None) -> bool:
    """True for Zara main/shore walks on beach/coast — force linen cover-up."""
    if not _place_is_shoreish(place):
        return False
    if not activity_key:
        return True  # coastal/beach MAIN
    return activity_key in _ZARA_SHORE_COVERUP_ACTIVITIES


def _place_is_shoreish(place: dict | None) -> bool:
    if not place:
        return False
    return bool(
        is_beach_place(place)
        or is_shore_sand_context(place)
        or (place.get("terrain_type") or "") == "coastal"
    )


def get_shore_coverup_outfit_override(character_key: str, place: dict | None = None) -> str:
    """Cover-up over swim for shore social / road moments — not pure bikini."""
    if character_key == "zara":
        return ZARA_SHORE_COVERUP
    if character_key == "ingrid":
        return (
            "SHORE COVER-UP (MANDATORY): Leather motorcycle jacket ON BODY or open over dark tee, "
            "leather pants or jeans, boots — NOT bikini. Helmet nearby ok."
        )
    if character_key == "jack_mae":
        return (
            "SHORE COVER-UP (MANDATORY — DUO): Jack denim shirt or tee + jeans/shorts + boots; "
            "Mae field shirt or light layer over practical swim/day kit + cargo or shorts + hiking boots. "
            "BOTH clothed for roadside/shore — not bikini/trunks-only lounge."
        )
    if character_key == "jonas_lara":
        return (
            "SHORE COVER-UP (MANDATORY — DUO): Jonas dark field jacket or sweater + cargos + boots; "
            "Lara olive field jacket or layer + cargos + hiking boots. BOTH field-day clothed — not beach lounge."
        )
    if character_key == "diaz":
        # Bikini-under-cover-up at beach tables → sexual soft_retry (Siesta Beach block log)
        return (
            "SHORE DAY CLOTHES (MANDATORY — DIAZ): Off-duty day kit only — jeans or shorts + tank/tee + sneakers "
            "or sandals. Bottoms fully visible. "
            "FORBIDDEN: bikini, one-piece, swim straps showing, open shirt over swim, cover-up-over-bikini, "
            "uniform/duty gear at the drinks table."
        )
    if character_key in {"luca", "chad", "conrad", "djordje", "driver_pov", "driver_van", "dale", "tyler", "miles"}:
        return (
            "SHORE COVER-UP (MANDATORY): Shirt or open linen shirt over swim shorts, or tee + shorts; "
            "sandals or shoes. NOT trunks alone at the table or vehicle. "
            + BOTTOMS_VISIBLE_LOCK
        )
    return f"{SHORE_COVERUP_OUTFIT_LOCK} {BOTTOMS_VISIBLE_LOCK}"


def get_road_travel_outfit_override(
    character_key: str, place: dict | None = None, activity_key: str | None = None,
) -> str:
    shore_coverup = False
    if character_key == "charlotte":
        base = (
            "ROAD/ARRIVAL OUTFIT (MANDATORY — CHARLOTTE): Complete city or travel kit with VISIBLE BOTTOMS always — "
            "black/charcoal pencil skirt + sheer back-seam nylons + pointed heels + blazer/blouse, "
            "OR dark jeans/wool trousers + flats + Barbour or tailored layer. Sutton Hoo pendant always. "
            "FORBIDDEN: oversized shirt as only garment; shirt-dress with bare thighs; no pants/skirt; "
            "linen shirt alone; beach cover-up as sole outfit."
        )
    elif character_key == "ingrid":
        base = (
            "ROAD/ARRIVAL OUTFIT (MANDATORY): Leather motorcycle jacket ON BODY, dark tee, leather pants or jeans, "
            "motorcycle boots. Helmet under arm or on bike. NOT swimwear. NOT barefoot."
        )
    elif character_key == "jack_mae":
        base = (
            "ROAD/ARRIVAL OUTFIT (MANDATORY — DUO): Jack faded denim shirt, worn jeans, leather boots; "
            "Mae olive field shirt, cargo trousers, hiking boots. BOTH stepping out of the pickup. "
            "NOT swimwear. NOT influencer vanlife kit."
        )
    elif character_key == "jonas_lara":
        base = (
            "ROAD/ARRIVAL OUTFIT (MANDATORY — DUO): Jonas dark field jacket, black sweater, cargos, hiking boots; "
            "Lara olive field jacket, cargos, hiking boots. BOTH stepping out of the dark green Volvo V70 XC. "
            "NOT swimwear. NOT city glam."
        )
    else:
        _city_curb = (activity_key or "") in _CITY_CURB_VEHICLE_ACTIVITIES
        if character_key in {"luca", "chad", "conrad", "djordje", "driver_pov", "driver_van", "dale", "tyler", "miles"}:
            if _place_is_shoreish(place) and not _city_curb:
                base = (
                    "ROAD/ARRIVAL OUTFIT (MANDATORY — coastal): Shirt or open linen shirt over swim shorts, "
                    "or tee + shorts; sandals or shoes. NOT trunks alone at the vehicle."
                )
            else:
                base = (
                    "ROAD/ARRIVAL OUTFIT (MANDATORY): Travel day clothes — shirt or tee, trousers or shorts, shoes. "
                    "NOT swim trunks alone at the vehicle. Arriving or leaving, not beach lounge."
                )
        elif _place_is_shoreish(place) and not _city_curb:
            # Coastal car = travel clothes with real bottoms — NOT open shirt over bikini
            # (shore cover-up with visible swim stays for biergarten/sunset drinks only)
            base = ROAD_TRAVEL_OUTFIT_LOCK
        else:
            base = ROAD_TRAVEL_OUTFIT_LOCK
    out = f"{base} {ARRIVAL_BOTTOMS_LOCK}"
    # Keep car shots on the same pinned day kit (not a fresh wardrobe invent)
    # Diaz on duty: day sticky is OFF DUTY jeans — never re-pin that at the vehicle
    if place and not shore_coverup:
        if character_key == "diaz" and diaz_should_be_on_duty(place, activity_key or "arrival"):
            out = (
                f"{out}\n{DIAZ_ON_DUTY_OUTFIT} "
                "At the vehicle: same ON DUTY uniform — NOT the OFF DUTY jeans/crop day kit."
            )
        else:
            _cont = get_day_outfit_continuity(character_key, place)
            if _cont:
                out = f"{out}\n{_cont}"
    return out

