# Plate continent: when EU-home vehicle is in US/Americas (or reverse), rewrite plates to local.
_US_PLATE_CLAUSE = re.compile(
    r"(?:"
    r"Georgia or North Carolina plates\s*\([^)]*\)|"
    r"(?:US|American|Arizona|California|Florida|Montana|Texas|Nevada|Midwest) plates(?:\s*\([^)]*\))?|"
    r"Mexican plates(?:\s*\([^)]*\))?|"
    r"Brazilian plates(?:\s*\([^)]*\))?|"
    r"plates?\s*\((?:US|AZ|CA|FL|MT|TX|NV|IL|GA|NC|MX|BR|CDMX)[^)]*\)"
    r")",
    re.I,
)
_EU_PLATE_CLAUSE = re.compile(
    r"(?:"
    r"Belgian or French plates\s*\([^)]*\)|"
    r"eastern European plates\s*\([^)]*\)|"
    r"(?:Belgian|French|German|Italian|Greek|Swedish|Norwegian|Czech|Romanian|Portuguese|"
    r"Spanish|Croatian|Serbian|Turkish|Monaco|British) plates(?:\s*\([^)]*\))?|"
    r"GB plates|"
    r"plates?\s*\((?:BE|FR|DE|IT|GR|SE|NO|CZ|RO|PT|ES|HR|RS|TR|MC|GB|NL|AT|CH|PL|HU|RU|UA|BZ)[^)]*\)|"
    r"\(BE/FR\)|\(RS/HR\)"
    r")",
    re.I,
)
_OTHER_PLATE_CLAUSE = re.compile(
    r"(?:Japanese plates(?:\s*\([^)]*\))?|plates?\s*\(JP[^)]*\))",
    re.I,
)


def _vehicle_plate_home(vehicle_desc: str) -> str | None:
    """Return 'us', 'eu', 'other', or None if no plate signal."""
    if not vehicle_desc:
        return None
    if _OTHER_PLATE_CLAUSE.search(vehicle_desc):
        return "other"
    us = bool(_US_PLATE_CLAUSE.search(vehicle_desc))
    eu = bool(_EU_PLATE_CLAUSE.search(vehicle_desc))
    if us and not eu:
        return "us"
    if eu and not us:
        return "eu"
    if us and eu:
        return None  # regional vehicles already branch
    return None


def _local_plate_lock(country_code: str, place_continent: str) -> str:
    cc = (country_code or "").upper()
    if place_continent == "us":
        if cc == "CA":
            return (
                "PLATE CONTINENT LOCK (MANDATORY): Canadian plates matching this province/territory. "
                "NO European blue-band plates (no BE/FR/DE/IT/GR/…). Same vehicle, local plates."
            )
        if cc == "MX":
            return (
                "PLATE CONTINENT LOCK (MANDATORY): Mexican plates (MX). "
                "NO European blue-band plates. Same vehicle, local plates."
            )
        if cc == "BR":
            return (
                "PLATE CONTINENT LOCK (MANDATORY): Brazilian plates (BR). "
                "NO European blue-band plates. Same vehicle, local plates."
            )
        return (
            "PLATE CONTINENT LOCK (MANDATORY): US state plates matching this location "
            "(FL if Florida coast, CA if California, AZ if Arizona, etc.). "
            "NO European blue-band plates (no BE/FR/DE/IT/GR/SE/CZ/…). "
            "Same make/model — long trip or local registration, not EU tourist plates."
        )
    return (
        f"PLATE CONTINENT LOCK (MANDATORY): local plates for this country ({cc or 'EU'}) — "
        "European-style plate with correct country code band if EU. "
        "NO US state plates, NO California/Florida/Arizona/Montana plates. "
        "Same make/model — local registration, not US tourist plates."
    )


def _strip_foreign_plate_clauses(vehicle_desc: str, place_continent: str) -> str:
    """Neutralize hardcoded home-continent plate phrases so the lock can win."""
    if place_continent == "us":
        out = _EU_PLATE_CLAUSE.sub("local plates for this location", vehicle_desc)
        return _OTHER_PLATE_CLAUSE.sub("local plates for this location", out)
    out = _US_PLATE_CLAUSE.sub("local plates for this location", vehicle_desc)
    return _OTHER_PLATE_CLAUSE.sub("local plates for this location", out)


def get_character_vehicle(
    character_key: str,
    country_code: str = "",
    *,
    place: dict | None = None,
    activity_key: str = "",
    on_duty: bool | None = None,
) -> str | None:
    # Diaz ON DUTY: same Tahoe platform, marked patrol unit (real agencies run both)
    if character_key == "diaz":
        duty = on_duty
        if duty is None and place is not None:
            duty = diaz_should_be_on_duty(place, activity_key)
        if duty:
            return DIAZ_ON_DUTY_VEHICLE
    regional = CHARACTER_VEHICLES_REGIONAL.get(character_key)
    if regional:
        # Americas (US/CA/MX/…) use US-side regional variant
        place_us = (country_code or "").upper() in AMERICAS_CODES or country_code == "US"
        return regional["US"] if place_us else regional["EU"]
    veh = CHARACTER_VEHICLES.get(character_key)
    if not veh or not country_code:
        return veh
    place_cont = get_base_layer(country_code)  # us or eu
    home = _vehicle_plate_home(veh)
    if home is None or home == place_cont:
        return veh
    # Mismatch (or JP/other abroad): rewrite plate language + hard lock
    adapted = _strip_foreign_plate_clauses(veh, place_continent=place_cont)
    return f"{adapted} {_local_plate_lock(country_code, place_cont)}"

