def _traffic_drive_lock(country_code: str) -> str:
    """Steering-wheel side + which side of the road — models invent UK RHD in Italy constantly."""
    cc = (country_code or "").upper()
    if cc in _RHD_COUNTRY_CODES:
        return (
            "\nTRAFFIC SIDE LOCK (MANDATORY): This country drives on the LEFT. "
            "RIGHT-HAND DRIVE — steering wheel on the RIGHT. Driver sits in the RIGHT front seat, "
            "hands on that wheel. Vehicle in the LEFT lane / left side of the road. "
            "FORBIDDEN: LHD wheel on left, driver in left seat of an RHD car, driving on the right."
        )
    return (
        "\nTRAFFIC SIDE LOCK (MANDATORY): This country drives on the RIGHT (continental / US / most of world). "
        "LEFT-HAND DRIVE — steering wheel on the LEFT. Driver sits in the LEFT front seat at that wheel. "
        "Vehicle travels in the RIGHT lane / right side of the road. "
        "FORBIDDEN: UK-style RHD (wheel on right), empty driver seat with her on the left of an RHD car, "
        "driving on the left side of the road."
    )


def _road_moment_ok(place_type: str) -> bool:
    """Scenic road moments (park/window) — outside cities only."""
    pt = (place_type or "").lower()
    if pt in _ROAD_MOMENT_CITY_TYPES:
        return False
    pt_u = (place_type or "").upper()
    return pt_u not in {"PPLC", "PPLA", "PPLA2"}


def _cruise_through_place_type_ok(place_type: str) -> bool:
    """Settlement street types + scenic drives that thread towns (Amalfi etc.)."""
    pt = (place_type or "").lower()
    pt_u = (place_type or "").upper()
    if pt in _CRUISE_THROUGH_PLACE_TYPES or pt == "scenic_drive":
        return True
    if pt_u in {"PPLC", "PPLA", "PPLA2", "PPL", "PPLA3", "PPLA4", "HBR", "PRT"}:
        return True
    return False


# No street-cruise on pure beach / nature-park landscapes (even if place_type is loose)
_CRUISE_THROUGH_BLOCK_LANDSCAPE = frozenset({"beach", "nature_park"})
# Bare alpine/desert scenic drives → window_down; coast/town drives keep cruise_through
_CRUISE_THROUGH_SCENIC_BLOCK_TERRAIN = frozenset({
    "high_mountains", "wilderness", "desert", "national_park",
})


def cruise_through_ok(place: dict | None = None, place_type: str = "") -> bool:
    """True only when place_type + landscape allow driving through the settlement / town-threaded drive."""
    pt = ((place or {}).get("place_type") if place else None) or place_type or ""
    if not _cruise_through_place_type_ok(pt):
        return False
    if place and is_shore_sand_context(place):
        return False
    if (pt or "").lower() == "scenic_drive" and place:
        terrain = (place.get("terrain_type") or "").lower()
        if terrain in _CRUISE_THROUGH_SCENIC_BLOCK_TERRAIN:
            return False
    if place:
        bucket = _landscape_bucket(
            place.get("terrain_type") or "",
            pt,
            place.get("name_en") or "",
        )
        if bucket in _CRUISE_THROUGH_BLOCK_LANDSCAPE:
            return False
    return True


def _cruise_through_ok(place_type: str) -> bool:
    """Back-compat: place_type-only check (prefer cruise_through_ok(place=...))."""
    return _cruise_through_place_type_ok(place_type)


def _character_has_road_vehicle(character_key: str) -> bool:
    if character_key in _NO_ROAD_VEHICLE_CHARS:
        return False
    if character_key == "driver_pov":
        return True
    return bool(get_character_vehicle(character_key))


def _road_moment_allowed(character_key: str, activity_key: str) -> bool:
    if activity_key not in _ROAD_MOMENT_ACTIVITIES:
        return True
    # cruise_through / scenic road: vehicle must be defined
    if not _character_has_road_vehicle(character_key):
        return False
    if character_key in _CHAUFFEURED_CHARS and activity_key in _CHAUFFEURED_NO_DRIVE_ACTIVITIES:
        return False  # never at the wheel
    if character_key == "zara" and activity_key == "window_down":
        return False
    return True


def get_character_vehicle_pose_class(
    character_key: str, activity_key: str, country_code: str = ""
) -> str:
    if character_key == "alessandra":
        return "road_bike" if activity_key == "park_with_view" else "car"
    if character_key == "stacy":
        return "jeep" if country_code == "US" else "car"
    if character_key in CHARACTER_VEHICLE_POSE_CLASS:
        return CHARACTER_VEHICLE_POSE_CLASS[character_key]
    veh = (get_character_vehicle(character_key, country_code) or "").lower()
    if "jeep" in veh or "wrangler" in veh:
        return "jeep"
    if any(
        x in veh
        for x in (
            "transporter", "trafic", "t3", "t4", "t5", "t6",
            "berlingo", "ducato", "california", "sprinter", "campervan",
        )
    ) or (" van" in f" {veh}" and "caravan" not in veh):
        return "van"
    if "bmw r" in veh or "r80" in veh or "r100" in veh:
        return "motorcycle"
    if "vespa" in veh:
        return "scooter"
    return "car"


def get_vehicle_activity_block(
    character_key: str, activity_key: str, country_code: str = "", place: dict | None = None
) -> str:
    if activity_key not in _ROAD_MOMENT_ACTIVITIES and activity_key not in {
        "car_exit", "stretch", "van_getting_dressed",
    }:
        return ""
    veh = get_character_vehicle(character_key, country_code)
    if character_key == "driver_pov":
        veh = (
            "Fiat Ducato campervan cab — hands on wheel, rosary on mirror, chess king on dash "
            "(see driver_pov spec). Driver never fully visible."
        )
    if not veh:
        return ""
    pose_class = get_character_vehicle_pose_class(character_key, activity_key, country_code)
    pose = VEHICLE_ACTIVITY_POSE.get(activity_key, {}).get(pose_class, "")
    if character_key in _CHAUFFEURED_CHARS:
        if activity_key == "park_with_view":
            pose = (
                "Parked — she is in or just exiting the REAR seat. Chauffeur stays at the wheel "
                "(barely visible / out of focus). She never sits in the driver's seat. "
                "Rear door open or just closing; gold pendant visible; slight smile."
            )
        elif activity_key in {"car_exit"}:
            pose = (
                "REAR door open — she is FULLY OUT already: both feet on pavement BESIDE the rear door, "
                "coat settling, clear gap between her body and the car sill. "
                "NOT mid-step out of the cabin, NOT one foot inside, NOT body through metal. "
                "Chauffeur remains in front (soft / not the subject). She never drives. "
                "First look around — she was already deciding before the car stopped."
            )
        elif activity_key == "stretch":
            pose = (
                "Beside the parked car (rear door or curb) — she stretches arms overhead. "
                "Chauffeur stays out of focus / in front seat. She never drives."
            )
        elif activity_key == "van_getting_dressed":
            pose = (
                "REAR door open — she changes at the back seat, back mostly to camera. "
                "Chauffeur stays in front (soft / not the subject). She never drives."
            )
        else:
            pose = (
                "REAR SEAT ONLY — chauffeur drives. She never holds the wheel. "
                "If moving: looking out side window from back seat."
            )
    shore = bool(place) and (
        is_shore_sand_context(place) or is_beach_place(place)
        or (place.get("terrain_type") or "") == "coastal"
    )
    if shore:
        block = (
            f"\n\nVEHICLE (if visible — match exactly; OUT OF FRAME preferred on beach): {veh}"
            "\nPLACEMENT: beach parking lot / access road behind dunes — OR omit vehicle entirely."
        )
        if pose:
            block += f"\nPOSE ({pose_class.upper()}, only if vehicle in frame): {pose}"
        block += VEHICLE_GEOMETRY_LOCK + SHORE_VEHICLE_PLACEMENT_LOCK
    else:
        block = f"\n\nVEHICLE (MANDATORY — match exactly): {veh}"
        if pose:
            block += f"\nPOSE ({pose_class.upper()}): {pose}"
        block += VEHICLE_GEOMETRY_LOCK
    if character_key in _CHAUFFEURED_CHARS:
        block += (
            "\nCHAUFFEUR LOCK (MANDATORY): She NEVER drives. No hands on wheel, no driver's seat. "
            "Chauffeur at the wheel (soft/anonymous). She is rear-seat power — exits rear door only."
        )
    elif activity_key in {"window_down", "cruise_through"} and pose_class in {"jeep", "car", "van"}:
        block += (
            "\nDRIVER LOCK (MANDATORY — shot fails if violated): She DRIVES — alone in the FRONT DRIVER SEAT "
            "at the steering wheel (same side as the wheel). Hands: one on wheel, other elbow on DRIVER door / arm out. "
            "FORBIDDEN: rear seat, back bench, rear-door arm-out, passenger seat, empty front seats with her in the back, "
            "chauffeur pose, pure rear chase that hides the wheel (models dump her in the back). "
            "CAMERA: front three-quarter or DRIVER-SIDE — windshield/A-pillar/wheel readable so the front seat is obvious."
        )
        if character_key == "tammy":
            block += (
                "\nTAMMY CROWN VIC LOCK (MANDATORY — common failure: dumping her in the back seat): "
                "She OWNS and DRIVES the white Crown Vic. FRONT DRIVER SEAT only (US LHD = left front). "
                "Left elbow on DRIVER door / left window fully down; right hand on wheel or gear. "
                "Steering wheel MUST be visible. Bumper stickers are on the REAR of the car — "
                "she is NOT sitting where the stickers are. "
                "FORBIDDEN: rear bench, rear door open with her leaning out, arm on rear window, "
                "body in the back while front seats empty, taillight/rear-quarter hero that hides the wheel. "
                "If the shot shows the rear bumper stickers as the main subject, REFRAME — "
                "driver-side or front three-quarter so cabin + wheel prove she is driving."
            )
        block += _traffic_drive_lock(country_code)
        if pose_class == "van" or "pop-up" in (veh or "").lower() or "california" in (veh or "").lower():
            block += POP_TOP_DRIVING_LOCK
    if character_key == "terry":
        block += (
            "\nTERRY LOOK LOCK (MANDATORY): Dark blonde with warm highlights, calm composed face — "
            "Belgian-French calibrated elegance. Attractive, sharp, never washed-out or tourist-frumpy. "
            "Yoga lean posture, long back. If swim/shore: black low-back one-piece (PRIMARY) — "
            "NOT a romper, NOT a boyshort onesie, NOT baggy. Early almost-smile ok. Face readable when she glances back."
        )
    return block

def _apply_vehicle_to_spec(
    char_spec: str,
    character_key: str,
    country_code: str,
    place: dict | None = None,
    activity_key: str = "",
    on_duty: bool | None = None,
) -> str:
    veh = get_character_vehicle(
        character_key, country_code, place=place, activity_key=activity_key, on_duty=on_duty,
    )
    if not veh or not char_spec:
        return char_spec
    import re
    if re.search(r"^VEHICLE:", char_spec, re.MULTILINE):
        return re.sub(r"^VEHICLE:.*$", f"VEHICLE: {veh}", char_spec, count=1, flags=re.MULTILINE)
    return char_spec.rstrip() + f"\n\nVEHICLE: {veh}\n"

def _sync_character_vehicles():
    import re
    for key, desc in CHARACTER_VEHICLES.items():
        if key not in CHARACTER_SPECS:
            continue
        spec = CHARACTER_SPECS[key]
        if re.search(r"^VEHICLE:", spec, re.MULTILINE):
            spec = re.sub(r"^VEHICLE:.*$", f"VEHICLE: {desc}", spec, count=1, flags=re.MULTILINE)
        else:
            spec = spec.rstrip() + f"\n\nVEHICLE: {desc}\n"
        CHARACTER_SPECS[key] = spec
    for key, variants in CHARACTER_VEHICLES_REGIONAL.items():
        if key not in CHARACTER_SPECS:
            continue
        desc = f"Europe: {variants['EU']} | US: {variants['US']}"
        spec = CHARACTER_SPECS[key]
        if re.search(r"^VEHICLE:", spec, re.MULTILINE):
            spec = re.sub(r"^VEHICLE:.*$", f"VEHICLE: {desc}", spec, count=1, flags=re.MULTILINE)
        else:
            spec = spec.rstrip() + f"\n\nVEHICLE: {desc}\n"
        CHARACTER_SPECS[key] = spec

_sync_character_vehicles()

