# Hamburg ≈ 53.55°N — cool-season knit hint for Europe / rest of world
_PULLI_LAT_HAMBURG = 53.55
# US/CA: Pacific NW / northern plains / New England — not half the contiguous US
_PULLI_LAT_US_CA = 47.0
_PULLI_CC_FALLBACK = frozenset({
    "NO", "SE", "FI", "IS", "DK", "EE", "LV", "LT", "FO", "GL", "SJ",
})
# Only cold months — no summer Pulli spam
_PULLI_MONTHS = frozenset({10, 11, 12, 1, 2, 3})
# Hard ban: Med / southern warm — never Mariusgenser even if spec mentions it
_SOUTH_NO_PULLI_CC = frozenset({
    "IT", "GR", "HR", "ES", "PT", "MA", "TN", "TR", "ME", "AL", "MC", "CY", "MT",
    "SI", "BA", "RS", "MK", "BG", "RO",
})


def is_northern_pulli_place(place: dict | None) -> bool:
    """True from Hamburg latitude north (EU/world), or ≥47°N in US/CA — cool season only."""
    if not place:
        return False
    if datetime.datetime.now().month not in _PULLI_MONTHS:
        return False
    cc = (place.get("country_code") or "").upper()
    try:
        lat = float(place.get("latitude"))
    except (TypeError, ValueError):
        return cc in _PULLI_CC_FALLBACK
    if cc in {"US", "CA"}:
        return lat >= _PULLI_LAT_US_CA
    return abs(lat) >= _PULLI_LAT_HAMBURG


def forbids_nordic_pulli(place: dict | None) -> bool:
    """Southern / Med / warm coast — thick Scandinavian wool Pulli is banned."""
    if not place:
        return False
    if is_northern_pulli_place(place):
        return False
    cc = (place.get("country_code") or "").upper()
    if cc in _SOUTH_NO_PULLI_CC:
        return True
    try:
        lat = abs(float(place.get("latitude")))
    except (TypeError, ValueError):
        return False
    t = (place.get("terrain_type") or "").lower()
    coastalish = (
        t in {"coastal", "beach", "lake"}
        or is_beach_place(place)
        or is_shore_sand_context(place)
    )
    if lat < 46.0 and coastalish:
        return True
    month = datetime.datetime.now().month
    if month in {5, 6, 7, 8, 9} and lat < 46.0:
        return True
    return False


# Outdoor / field / athlete — wool knit OR clean technical fleece when cool
_PULLI_FLEECE_OK = frozenset({
    "werra", "dale", "tyler", "maya", "kay", "metka", "alessandra",
    "jack_mae", "jonas_lara", "chad",
})
# Nordic wool icons — Norweger / Mariusgenser, not Polartec tourist
# katja: Norweger only in CHARACTER_SPECS cool block — not here (avoids 2× Mariusgenser spam)
_PULLI_WOOL_NORDIC = frozenset({"ingrid", "sigrid", "conrad"})
_NO_PULLI_CHARS = _PULLI_WOOL_NORDIC | {"katja"}


def get_northern_pulli_lock(place: dict | None, character_key: str | None = None) -> str:
    """Soft cool-season knit hint for northern latitudes — not every shot a sweater."""
    if forbids_nordic_pulli(place):
        return ""
    if not is_northern_pulli_place(place):
        return ""
    cc = ((place or {}).get("country_code") or "").upper()
    char = (character_key or "").lower()
    _band = "US/CA ≥47°N, Oct–Mar" if cc in {"US", "CA"} else "Hamburg+ lat, Oct–Mar"
    if char in _PULLI_FLEECE_OK:
        return (
            f"COOL-SEASON LAYER (soft — {_band}): knit or clean technical fleece Pulli often fits "
            "(half-zip/crew — navy, grey, forest, black, oatmeal) — OR tee/shirt + light jacket. "
            "Do NOT force a heavy sweater every shot. Chad: fleece vest over tee ok. "
            "NOT tank-top tourist, NOT linen resort, NOT loud souvenir logo fleece."
        )
    if char in _PULLI_WOOL_NORDIC:
        return (
            f"COOL-SEASON LAYER (soft — {_band}): Norwegian wool knit / Mariusgenser-style often fits "
            "(oatmeal, grey, navy) — OR shirt + open jacket. Do NOT force a Pulli every shot. "
            "NOT fleece tourist, NOT tank-top."
        )
    return (
        f"COOL-SEASON LAYER (soft — {_band}): fine wool/merino knit often fits "
        "(oatmeal, grey, navy, forest, black) — OR blouse/shirt + light jacket/coat. "
        "Do NOT force a sweater every shot. NOT fleece, NOT linen vacation, NOT tank-top tourist."
    )


def get_no_nordic_pulli_lock(place: dict | None, character_key: str | None = None) -> str:
    """Hard ban — overrides CHARACTER_SPECS sweater lines in Med / south heat."""
    char = (character_key or "").lower()
    if char not in _NO_PULLI_CHARS:
        return ""
    if not forbids_nordic_pulli(place):
        return ""
    return (
        "HEAT / SOUTH WARDROBE LOCK (MANDATORY — overrides any sweater line in the character brief):\n"
        "NO Norwegian Pulli, NO Mariusgenser, NO Lusekofte, NO thick oatmeal/grey geometric wool sweater.\n"
        "Southern / Mediterranean / warm coast — thick Scandinavian knit = FAIL.\n"
        "Ingrid: Falcon leather open over fitted tank/tee + dark pants or shorts, OR beach one-piece / "
        "athletic swim on shore; barefoot ok on sand. Light layers only — no Pulli."
    )


def get_season_context(country_code: str) -> str:
    month = datetime.datetime.now().month
    COLD = ["EE","LV","LT","FI","NO","IS","DK","PL","CZ","SK","DE","AT","CH","GB","SE"]
    WARM = ["IT","GR","HR","ES","PT","MA","TN","TR","ME","AL","MC","SI","RS","BA","MK","BG","RO","HU"]
    HOT  = ["BR","MX","TN","MA"]

    if country_code in HOT:
        return "warm tropical or desert climate — minimal summer clothing year-round, bikini/light dress natural"
    if country_code in WARM:
        if month in [6,7,8]:
            return "Mediterranean summer — light clothing, sandals, bare skin natural, golden light"
        elif month in [12,1,2]:
            return "mild Mediterranean winter — light jacket open, boots, scarf optional"
        else:
            return "Mediterranean spring or autumn — light layers, linen, relaxed"
    if country_code in COLD:
        if month in [6,7,8]:
            return "Northern European summer — light clothing, NOT tropical"
        elif month in [12,1,2]:
            return "Northern European winter — warm coat, scarf, boots"
        elif month in [3,4,5]:
            return "Northern European spring — light jacket, layers, cool but bright"
        else:
            return "Northern European autumn — jacket, boots, muted tones"
    if country_code in ["US","CA"]:
        if month in [6,7,8]:
            return "American summer — casual, shorts or light dress ok depending on terrain"
        elif month in [12,1,2]:
            return "American winter — varies by region, check terrain"
        else:
            return "mild American spring or autumn — casual layers"
    return "temperate climate, casual travel clothing appropriate for the location"

