def naomi_land_main_ok(
    character_key: str,
    place: dict | None,
    activity_key: str | None = "",
) -> bool:
    """True for Naomi MAIN on city / settlement — Prague land look."""
    if character_key != "naomi" or activity_key:
        return False
    if not place:
        return False
    if is_beach_place(place) or _place_is_shoreish(place):
        return False  # beach uses NAOMI_BEACH_MAIN_LOCK
