def is_diaz_border_place(place: dict | None) -> bool:
    """US/MX frontera — where Diaz can be on duty in uniform."""
    if not place:
        return False
    cc = (place.get("country_code") or "").upper()
    if cc not in {"US", "MX"}:
        return False
    hay = f"{place.get('name_en', '')} {place.get('state_name', '')}".lower()
    # Baja California Sur (La Paz, Cabo, …) is NOT the northern border strip
    if "baja california sur" in hay or "b.c.s" in hay or "bcs" == (place.get("state_code") or "").lower():
        return any(k in hay for k in _DIAZ_BORDER_PLACE_KEYS)
    if any(k in hay for k in _DIAZ_BORDER_PLACE_KEYS):
        return True
    state = (place.get("state_name") or "").lower()
    if any(k in state or k in hay for k in _DIAZ_BORDER_STATE_KEYS):
        # Texas is huge — require border place key OR south-TX name cues
        if "texas" in state or "texas" in hay:
            return any(k in hay for k in _DIAZ_BORDER_PLACE_KEYS) or any(
                k in hay for k in ("laredo", "el paso", "mcallen", "brownsville", "rio grande", "border")
            )
        return True
    # Baja California (Norte) twin cities only — already covered by place keys; Ensenada etc. off
    if "baja california" in state or "baja california" in hay:
        return any(k in hay for k in _DIAZ_BORDER_PLACE_KEYS)
    return False


# CLI --diaz-on-duty: full uniform pass on border places (100%, not ~45%)
_DIAZ_FORCE_ON_DUTY = False
# Sticky per place-set: ONE decision for the whole set — uniform OR civilian, never mixed
_DIAZ_SET_ON_DUTY: bool | None = None


def set_diaz_force_on_duty(on: bool) -> None:
    global _DIAZ_FORCE_ON_DUTY
    _DIAZ_FORCE_ON_DUTY = bool(on)


def ensure_diaz_set_duty(place: dict | None) -> bool:
    """Roll on-duty once for this place-set. Same answer for every shot in the set."""
    global _DIAZ_SET_ON_DUTY
    if not is_diaz_border_place(place):
        _DIAZ_SET_ON_DUTY = False
        return False
    if _DIAZ_FORCE_ON_DUTY:
        _DIAZ_SET_ON_DUTY = True
        return True
    if _DIAZ_SET_ON_DUTY is None:
        # Shore / beach border towns: whole set civilian (no one-shot uniform)
        if place and is_shore_sand_context(place):
            _DIAZ_SET_ON_DUTY = False
        else:
            _DIAZ_SET_ON_DUTY = random.random() < 0.45
        if _DIAZ_SET_ON_DUTY:
            print("  🚓 Diaz SET ON DUTY — uniform for entire place-set")
        else:
            print("  👕 Diaz SET OFF DUTY — civilian for entire place-set")
    return bool(_DIAZ_SET_ON_DUTY)


def diaz_set_is_on_duty(place: dict | None = None) -> bool:
    """True if this place-set is locked on duty (sticky or --diaz-on-duty)."""
    if _DIAZ_FORCE_ON_DUTY and is_diaz_border_place(place):
        return True
    if _DIAZ_SET_ON_DUTY is not None:
        return bool(_DIAZ_SET_ON_DUTY)
    return ensure_diaz_set_duty(place)


def diaz_should_be_on_duty(
    place: dict | None,
    activity_key: str = "",
    *,
    force: bool = False,
) -> bool:
    """On duty for the ENTIRE place-set when sticky/force says so — activity_key ignored.
    Swim/hike etc. must not be picked on on-duty sets (filtered elsewhere); if they slip through, still uniform.
    ~45% of border place-sets; never inland MX / La Paz BCS / non-border."""
    if force:
        return bool(is_diaz_border_place(place))
    return diaz_set_is_on_duty(place)


def get_diaz_off_duty_lock(character_key: str, *, allow_police_markers: bool = False) -> str:
    """Legacy name: returns off-duty lock, or empty if police markers allowed (on duty)."""
    if character_key != "diaz":
        return ""
    if allow_police_markers:
        return DIAZ_ON_DUTY_LOCK.strip()
    return DIAZ_OFF_DUTY_NO_POLICE_LOCK.strip()


