_REGINA_ALWAYS_ACTIVITIES = ("passants", "power_aura", "amulet_glow")
_REGINA_ALLOWED_ACTIVITIES = frozenset(_REGINA_ALWAYS_ACTIVITIES)


def ensure_regina_signature_activities(
    character_key: str,
    acts: list,
    activity_key: str | None,
) -> list:
    """Regina: only passants + power_aura + amulet_glow. Nothing else."""
    if character_key != "regina":
        return acts or []
    allowed = [a for a in _REGINA_ALWAYS_ACTIVITIES if a not in DISABLED_ACTIVITIES]
    if activity_key:
        if activity_key in DISABLED_ACTIVITIES:
            return []
        if activity_key not in _REGINA_ALLOWED_ACTIVITIES:
            print(f"  ⏭️ Regina blocks '{activity_key}' — only: {', '.join(allowed)}")
            return []
        return [activity_key]
    print(f"  ⭕ Regina set: only {', '.join(allowed)}")
    return allowed


def claim_tammy_energy_drink(chance: float = 1.0) -> bool:
    """At most one energy-drink can per Tammy set; ~40% of sets allow one at all."""
    global _tammy_energy_drink_claimed
    if not _tammy_energy_drink_set_ok or _tammy_energy_drink_claimed:
        return False
    if chance < 1.0 and random.random() >= chance:
        return False
    _tammy_energy_drink_claimed = True
    return True


def get_tammy_energy_drink_line(allowed: bool) -> str:
    if allowed:
        return (
            "ENERGY DRINK (this shot only — max once per set): one generic gas-station can "
            "in hand or beside her — bottom shelf, no recognizable brand."
        )
    return "NO energy drink can in hand, on table, or beside her this shot."


def get_tammy_mouth_prop_lock(character_key: str, *, energy_drink: bool = False) -> str:
    if character_key != "tammy":
        return ""
    return f"{TAMMY_MOUTH_PROP_LOCK.strip()}\n{get_tammy_energy_drink_line(energy_drink)}"


_LUCA_NO_MOKA_ACTIVITIES = frozenset({
    "going_for_a_run", "trail_running", "morning_run_urban", "cycling_road", "hiking_back", "snowshoe_hike", "desert_walk",
    "kajak_sup", "sup_mount", "sup_entry", "kayak_entry", "surf_paddle", "surfing",
    "beach_walk_distance", "muscheln_sammeln", "sailing", "board_carry", "gear_haul", "tank_carry",
    "rope_coil", "chin_up", "bike_push", "helmet_off",
})


def luca_moka_eligible(terrain: str = "", activity_key: str = "", dayhike_mode: bool = False) -> bool:
    if dayhike_mode or activity_key in _LUCA_NO_MOKA_ACTIVITIES:
        return False
    if activity_key in _SWIM_OUTFIT_ACTIVITIES:
        return False
    return True


def luca_moka_roll(terrain: str = "", activity_key: str = "", dayhike_mode: bool = False) -> bool:
    return luca_moka_eligible(terrain, activity_key, dayhike_mode) and random.random() < 0.62


# Smartphones: Chad + Tyler. Charlotte: call/handset. Tammy: prepaid burner only. Everyone else: none.
_PHONE_OK_CHARS = frozenset({"chad", "tyler", "charlotte", "tammy"})


def get_phone_prop_lock(character_key: str) -> str:
    """Phone policy — analog timeline; only listed exceptions may show a handset."""
    if character_key == "chad":
        return (
            "PHONE OK (CHAD): Smartphone visible — doomscroll, selfie-stream, or AirPods+phone. "
            "He is the only full smartphone bro in this timeline."
        )
    if character_key == "tyler":
        return (
            "PHONE/GEAR OK (TYLER): Creator tools ok — smartphone, mirrorless flip-screen, gimbal. "
            "Work check, not vacant doomscroll. NOT Chad tourist-stream energy."
        )
    if character_key == "charlotte":
        return (
            "PHONE OK (CHARLOTTE): Handset mid-call or in hand — City/meeting energy. "
            "Held to ear or half-ignored in palm. NOT scrolling, NOT selfie, NOT content."
        )
    if character_key == "tammy":
        return (
            "BURNER PHONE OK (TAMMY): Prepaid burner only — sometimes, for research. "
            "Small cheap flip/dumb handset or plain prepaid brick. "
            "NOT an iPhone, NOT Instagram, NOT scrolling a bright glass slab. Often no phone in frame."
        )
    if character_key == "maya":
        # Main heroes kept inventing phone-check (St. Augustine block) — harden beyond generic NO PHONE
        return (
            "NO PHONE (MAYA — MANDATORY): She does not use a smartphone. Hands empty or on cap/water bottle/Jeep. "
            "FORBIDDEN: phone in either hand, both hands on a screen, looking down at a device, texting, GPS, selfie. "
            "Eyes on water, horizon, Jeep, or middle distance — never a glass slab."
        )
    return (
        "NO PHONE (MANDATORY): No smartphone in hand, on table, in pocket as visible prop, or in frame. "
        "NEVER looking at a phone screen, scrolling, texting, or selfie. "
        "Analog props only (book, map, notebook, camera if character-owned). "
        "Exceptions elsewhere: Chad, Tyler, Charlotte, Tammy burner — not this character."
    )


def get_luca_moka_prop_lock(
    character_key: str,
    *,
    terrain: str = "",
    activity_key: str = "",
    dayhike_mode: bool = False,
    moka: bool | None = None,
) -> str:
    if character_key != "luca":
        return ""
    if not luca_moka_eligible(terrain, activity_key, dayhike_mode):
        return (
            "LUCA PROP LOCK: NO Moka pot — running, paddling, swimming, hiking, or on water. "
            "Beer can or board leash ok."
        )
    if moka is None:
        moka = random.random() < 0.62
    if moka:
        return (
            "LUCA MOKA RUNNING GAG (this shot): small stovetop Moka pot — in hand, on van step, "
            "open van doorway, or café table edge. Bialetti-style battered aluminum, lived-in, not new. "
            "Casual ritual, not posed. Morning energy even if afternoon."
        )
    return "LUCA PROP LOCK: no Moka this shot — beer can ok."


def get_ingrid_falcon_jacket_lock(
    character_key: str,
    outfit_override: str | None = None,
    *,
    nightlife_mode: bool = False,
    noir_mode: bool = False,
    eclipse_mode: bool = False,
    viper_mode: bool = False,
    maxpower_mode: bool = False,
) -> str:
    if character_key != "ingrid":
        return ""
    _oo = (outfit_override or "").lower()
    if any(
        x in _oo
        for x in (
            "jacket off",
            "leather off",
            "no leather",
            "without jacket",
            "swimwear",
            "bikini",
            "one-piece",
            "run outfit",
            "trail runners",
            "athletic shorts",
            "not on body",
            "norwegian sweater",
            "norweger",
            "mariusgenser",
            "lusekofte",
        )
    ):
        return ""
    # No kink/PVC night variant — road Falcon leathers stay day and night
    return INGRID_FALCON_JACKET_LOCK.strip()


