def mark_wet_continuity(place: dict) -> None:
    pid = str(place.get("id") or place.get("name_en") or "")
    if pid:
        _WET_CONTINUITY_PLACE_IDS.add(pid)


def consume_wet_continuity(place: dict) -> bool:
    pid = str(place.get("id") or place.get("name_en") or "")
    if pid in _WET_CONTINUITY_PLACE_IDS:
        _WET_CONTINUITY_PLACE_IDS.discard(pid)
        return True
    return False


def get_cast_micro_detail_locks(
    character_key: str,
    place: dict,
    *,
    activity_key: str = "",
    outfit_override: str | None = None,
    shot: str = "main",
) -> str:
    """Small mandatory flavor locks — signature props, locale micro, continuity."""
    parts: list[str] = []
    terrain = (place.get("terrain_type") or "").lower()
    pt = (place.get("place_type") or "").lower()
    act = activity_key or ""
    oo = (outfit_override or "").lower()
    waterish = act in _SWIM_OUTFIT_ACTIVITIES or act in {
        "beach_walk_distance", "muscheln_sammeln", "surf_paddle", "surfing",
    }

    if character_key == "valentina":
        if act in _VALENTINA_CHESS_ACTIVITIES or (not act and shot == "main" and not waterish):
            if random.random() < 0.55:
                parts.append(
                    "VALENTINA CHESS QUEEN (subtle): black chess queen somewhere in frame — "
                    "wall edge, table corner, railing, or jacket pocket edge. Never prominent, never explained. "
                    "NOT on water/SUP."
                )
        elif waterish:
            parts.append("NO chess queen in water/beach swim shots.")

    if character_key == "kay" and terrain in {"coastal", "lake"} and not act:
        if random.random() < 0.35:
            parts.append(
                "KAY SIGNATURE (this shot): peeling wetsuit off her shoulders while already walking — "
                "mid-motion, not posed. Coastal/water context only."
            )

    if character_key == "dale" and (
        terrain in {"desert", "coastal"}
        or pt in {"beach"}
        or "ghost" in (place.get("name_en") or "").lower()
    ):
        if act in {"", "desert_walk", "beach_walk_distance", "roadside_dusk", "park_with_view", "muscheln_sammeln"}:
            if random.random() < 0.50:
                _where = "wet sand / tide line" if terrain == "coastal" or pt == "beach" else "desert scrub / ghost-town dirt"
                parts.append(
                    f"DALE SIGNATURE: metal detector in hand or coil near ground — headphones on, "
                    f"slow sweep arc over {_where}. Not a tourist selfie prop. Patient, slightly eccentric."
                )

    if character_key == "charlotte":
        parts.append(
            "CHARLOTTE SUTTON HOO (MANDATORY): gold filigree pendant at collarbone — always visible, "
            "including swim/one-piece. Never removed. Union Jack lapel pin only when dressed (not swim). "
            "Travel/cool/outdoors (not city pencil kit, not swim): prefer real Barbour waxed jacket — olive/navy/classic green."
        )

    if character_key == "ana":
        parts.append(
            "ANA GOLD (MANDATORY when legs/feet/ankle readable): gold anklet LEFT ankle + small gold toe ring "
            "LEFT foot. Nose stud left nostril if face readable. Never right ankle/foot."
        )

    if character_key == "thea":
        if act in {"beer_crate", "muscle_flex"}:
            parts.append(
                "THEA WORK BEAT: beer crate / heavy haul allowed this shot only — taverna/harbour work context, "
                "not beach swim fashion with crates."
            )
        else:
            parts.append(
                "THEA NO CRATES (MANDATORY): NO beer crates, NO bottle crates, NO gas bottles in hands or frame. "
                "Hands free or cigarette/sunglasses only. Strength is in her posture — not props. "
                "She is off-duty / beach / waiting / street — crates are work-shift only."
            )

    # Duo investigators — maps/coffee are occasional, not costume defaults
    _duo_map_acts = {
        "map_hood", "historical_map_compare", "field_notes", "binoculars_scan",
        "fence_line_scan", "wind_farm_scan", "doc_pair_frame",
    }
    if character_key == "jack_mae":
        if act in _duo_map_acts or act == "diner_booth":
            pass  # activity may use notebook/map/coffee in context
        else:
            parts.append(
                "JACK & MAE PROP LOCK: Hands empty by default — pockets, sides, or one hand on pickup. "
                "NO paper map in hands this shot. NO coffee mug in Jack's hand this shot "
                "(coffee only at diner table when the scene is clearly a diner). "
                "Binoculars/notebook only if the activity requires them. Looking at the place is enough."
            )
    if character_key == "jonas_lara":
        if act in _duo_map_acts:
            pass
        else:
            parts.append(
                "JONAS & LARA PROP LOCK: Hands empty by default. "
                "NO paper map in hands this shot. NO compass held up. "
                "Nikon FM2 may hang unused on Jonas's strap — not raised every frame. No Leica. "
                "Notebook only if the activity is field_notes. Looking at the place is enough."
            )

    if character_key == "diana":
        parts.append(
            "DIANA FACE LOCK (MANDATORY every shot): "
            "Face = canonical EXACTLY — same bone structure AND same goth makeup: "
            "deep red lacquer lips, dark winged eyeliner + smoky lid (never nude lips, never no-makeup). "
            "VERY pale / porcelain white skin — never olive, never warm, never bronzer "
            "(overrides any premium layer). Sharp pores. Hands OFF the face."
        )
        # Sombre contract/Transylvania register — not wind-farm / logistics "change" infra
        if (
            shot == "main"
            and not act
            and not waterish
            and random.random() < 0.38
        ):
            parts.append(
                "DIANA AMBIENT (subtle, secondary): "
                + random.choice((
                    "wet cobblestone or thin fog at the edges; the square feels mid-pause — few people, not horror-empty",
                    "a closed chapel, notary, or old institutional door in mid-ground — soft, unread hours, not the subject",
                    "blue-hour or overcast hush — city feels between appointments; no slogans, no crowd-as-message",
                ))
            )

    if character_key == "elena":
        parts.append(
            "ELENA FACE LOCK (MANDATORY every shot, including daylight/city/activities): "
            "Match canonical face EXACTLY — bone structure, eye spacing, nose, lip shape, platinum blonde bob. "
            "VERY pale Slavic skin — NEVER bronzed, NEVER warm beach glow, NEVER tanned "
            "(overrides any premium layer / eclipse bronzer). "
            "Face SHARP: pores, real texture, slight festival fatigue around eyes ok — crisp eyes. "
            "NO beauty blur, NO soft-focus, NO airbrush mush, NO melted/smudged features. "
            "Hands OFF the face/jaw/neck — nothing touching or occluding the face. "
            "NOT soft tourist makeup, NOT influencer soft glam, NOT magazine-cover perfection. "
            "If the face is soft, generic, or unrecognizable as Elena, the shot has failed."
        )

    if character_key == "sofia":
        parts.append(
            "SOFIA MARKER LOCK (MANDATORY every shot): "
            "Face = canonical EXACTLY — olive freckled surfer, dark wavy hair, sun-squint. "
            "ALWAYS visible: thin silver crescent moon necklace + blue woven bracelet LEFT wrist. "
            "If bracelet or crescent missing, the shot has failed. Not a generic beach brunette."
        )

    if character_key == "maria":
        parts.append(
            "MARIA MARKER LOCK (MANDATORY every shot): "
            "Face = canonical EXACTLY — Andalusian / Penélope-Cruz energy, strong features, warm olive. "
            "ALWAYS: small gold earrings visible. Expression still/complete — never tourist grin, never soft influencer smile. "
            "Not a generic pretty brunette in black."
        )

    if character_key == "stacy":
        parts.append(
            "STACY MARKER LOCK (MANDATORY every shot): "
            "Face = canonical EXACTLY — Midwest American 22, blonde, freckles, open wonder (not soft European cool). "
            "ALWAYS: disposable camera on strap around neck (visible). Scrunchie on wrist and/or small gold hoops. "
            "Converse when feet visible. Not a generic tourist blonde without the camera."
        )

    if character_key == "chad":
        parts.append(
            "CHAD FACE LOCK (MANDATORY every shot): stumpfer Bro — slightly vacant eyes, no irony, "
            "no quiet intelligence, no mysterious gaze. Handsome and a bit thick. Friendly-blunt, "
            "content-speak vibes energy without understanding them. NEVER sophisticated, NEVER dark, "
            "NEVER thoughtfully introspective. Bro-Haftigkeit always readable on the face."
        )
        if act == "surprise_rain":
            parts.append(
                "CHAD SURPRISE RAIN (MANDATORY): MacBook clutched against his chest or under one arm — "
                "he is trying to keep it dry. Jacket or fleece (Patagonia-vest energy ok here) yanked over "
                "the laptop like a tent, shoulders hunched, rain on his hair and the jacket fabric. "
                "ChatGPT-sticker MacBook half-visible under the jacket edge. Vacant Bro face — mild panic "
                "about the machine, not the weather. Acai bowl abandoned or ruined nearby optional. "
                "NO umbrella fashion pose — pure digital-nomad damage control."
            )
        else:
            # MacBook often, not always — including beach. Never mid-paddle/run/trail.
            _chad_hard_no = (
                act in _CHAD_MACBOOK_HARD_NO
                or act in _SWIM_OUTFIT_ACTIVITIES
            )
            if _chad_hard_no:
                parts.append(
                    "CHAD NO MACBOOK (this shot): mid-activity — no laptop. "
                    "AirPods / Apple Watch / phone doomscroll ok. Vacant Bro face."
                )
            else:
                _beachy = is_shore_sand_context(place) or is_beach_place(place) or act in {
                    "beach_walk_distance", "muscheln_sammeln",
                }
                if act in _CHAD_MACBOOK_ACTIVITIES or (shot == "main" and pt in _CHAD_MACBOOK_PLACE_TYPES and not _beachy):
                    _p = _CHAD_MACBOOK_P_URBAN
                elif _beachy:
                    _p = _CHAD_MACBOOK_P_BEACH
                else:
                    _p = _CHAD_MACBOOK_P_OTHER
                if random.random() < _p:
                    _where = (
                        "on a towel, beach bag, or low wall beside him — absurd but intentional digital-nomad beach energy"
                        if _beachy
                        else "open nearby or on table/lap"
                    )
                    parts.append(
                        f"CHAD MACBOOK (this shot): MacBook {_where} — ChatGPT tab energy, "
                        "unknown-startup sticker \"Built with AI\". Acai/coffee ok. His job, not a prop."
                    )
                else:
                    parts.append(
                        "CHAD NO MACBOOK (this shot): laptop off-frame. "
                        "AirPods / Apple Watch / phone doomscroll ok. Vacant Bro face."
                    )

    if character_key == "tammy":
        clavicle_open = (
            waterish
            or act in _TAMMY_CLAVICLE_OPEN_ACTIVITIES
            or any(x in oo for x in ("tank", "bikini", "one-piece", "swimsuit", "open collar", "low neck"))
        )
        if clavicle_open and "high neck" not in oo and "flannel buttoned" not in oo:
            parts.append(
                "TAMMY TATTOO (if LEFT clavicle visible): only \"11.22.63\" small faded black ink on LEFT collarbone. "
                "If jacket/high neck covers clavicle — omit tattoo, do not invent other tattoos. "
                "Golden apple is NECK PENDANT only — never an apple tattoo."
            )
        else:
            parts.append(
                "TAMMY TATTOO: clavicle covered — do NOT show \"11.22.63\" through clothes; "
                "no other tattoos. Golden apple pendant at neck ok if neckline shows."
            )

    if character_key == "ingrid":
        jacket_on = bool(get_ingrid_falcon_jacket_lock(character_key, outfit_override))
        if jacket_on and shot == "main" and random.random() < 0.18:
            parts.append(
                "INGRID BACK ANGLE (this shot): three-quarter back or from behind so the FALCON jacket graphic "
                "reads clearly between the shoulder blades — not a pure face-front portrait."
            )

    if character_key == "sigrid":
        parts.append(
            "SIGRID HEL MARKERS (MANDATORY): thin gold half-ring (open, looks broken) on index or middle finger "
            "if hands readable; one small gold stud on ONE ear only — other ear bare. Never symmetrical ears. "
            "Subtle HEL asymmetry in clothing when dressed (one shoulder/lapel/tuck slightly absent)."
        )
        if not waterish and act not in {"going_for_a_run", "trail_running", "morning_run_urban", "hiking_back", "snowshoe_hike"}:
            if random.random() < 0.55:
                parts.append(
                    "SIGRID PROP (this shot): thin black Moleskine with Rotring pen clipped — "
                    "pen half matte black / half bare metal. Never a laptop in public."
                )

    if character_key == "djordje":
        if act not in {"going_for_a_run", "trail_running", "kajak_sup", "sup_mount", "sup_entry", "surf_paddle", "surfing"}:
            if random.random() < 0.60:
                parts.append(
                    "DJORDJE DICE (this shot): two or three dice somewhere in frame — table ledge, dashboard, "
                    "bar, café edge — different sizes/materials. Not being rolled. Never explained."
                )

    if character_key == "kelek":
        parts.append(
            "KELEK COMPASS (MANDATORY when belt/hip readable): small brass compass on belt — old, functional, "
            "not decorative souvenir. Annotated paper map nearby only if seated/stopped (rock, hood, wall)."
        )

    if character_key == "yosra":
        parts.append(
            "YOSRA RA MARKER (MANDATORY): Eye of Ra visible in at least one prop — gold badge on camera bag, "
            "and/or thin worn gold Eye of Ra pendant/charm at wrist or neck. Never fully hidden. "
            "Leica M6 energy when camera in frame."
        )

    if character_key == "mila":
        parts.append(
            "MILA WRISTBANDS (MANDATORY when that wrist/arm readable): three or four festival wristbands — "
            "different colours, stacked on ONE wrist. She never removes them. "
            "Band logo tee optional only; plain black more often."
        )

    if character_key == "jelena":
        parts.append(
            "JELENA PHYSIQUE (mandatory): soft hourglass — narrow waist, natural full chest/hips, "
            "full round glutes — KEEP volume, never flatten or shrink the seat. "
            "Body under clothes — never flat/pencil/runner-thin."
        )

    if character_key == "isabella":
        parts.append(
            "ISABELLA LOCK (MANDATORY): thin old gold bracelet LEFT wrist when arm readable — family piece, never removed, including swim. "
            "Quiet elegance — never raises her voice, never Miami glam. Espresso/tea only indoors/café. "
            "Phone rare; if present, short calm call already solving something. Cool Atlantic light, not tropical bronze. "
            "BOTTOMS: skirt preferred (leather or fabric mini/midi) OR elegant trousers — NEVER shorts/cutoffs on land. "
            "Day outfit when not swim/run/hike: leather OR fabric mini/midi + fine knit/blouse — OR dusty-rose blouse + dark fabric pencil + loafers (town/sunset). Quiet, not club."
        )

    if character_key == "luca":
        parts.append(
            "LUCA FACE/APPEAL LOCK (MANDATORY): weirdly attractive van-bum — NOT surfer-handsome, "
            "NOT Baywatch, NOT Calvin Klein beach model, NOT chiselled jaw / symmetrical male-model face. "
            "Slightly odd, sun-damaged, soft irregular features, hair too long and mussed. "
            "Lived-in charisma only. If he looks like a casting-call surfer, the shot has failed."
        )

    # Beach wet: hair often on shore; body wet only after real water action (not beach stroll)
    if character_key not in _BEACH_WET_SKIP_CHARS:
        if act in _BODY_WET_ACTIVITIES:
            parts.append(
                "BODY WET (water action): hair and skin visibly wet from the water — "
                "natural documentary sheen, not glamour oil, not fetish fabric-cling. "
                "Hair flat or salt-pushed back."
            )
        else:
            _beach_land = (
                act in _BEACH_HAIR_WET_ACTIVITIES
                or pt == "beach"
                or (
                    terrain in {"coastal", "lake"}
                    and shot == "main"
                    and not act
                    and not is_urban_place(place)
                )
            )
            if _beach_land and random.random() < BEACH_HAIR_WET_P:
                parts.append(
                    "HAIR WET (beach): hair damp or salt-tousled / flat — sea air or a recent dip. "
                    "Body NOT soaked, NOT dripping; fabric NOT clinging from water. "
                    "Light skin sheen from salt air only."
                )

    if consume_wet_continuity(place) and not waterish:
        parts.append(
            "WET CONTINUITY (subtle): hair still damp or salt-tousled from recent water; skin lightly salt-kissed — "
            "not dripping, not towel-perfect dry. Same person, five minutes later."
        )

    # Soft edge-of-place ambient — EU village/small_town mains (not duos/werra/diana)
    # Diana has her own sombre ambient; duos/werra use BACKGROUND INFRA
    if (
        character_key not in {"jonas_lara", "jack_mae", "werra", "diana"}
        and CHAR_HOME_CONTINENT.get(character_key) == "eu"
        and pt in {"village", "small_town"}
        and shot == "main"
        and not act
        and terrain not in {"coastal", "beach", "lake"}
        and random.random() < 0.20
    ):
        parts.append(
            "PLACE EDGE (subtle, secondary): far edge of frame may show one quiet mark — "
            "half-finished houses, a new warehouse box, or a shuttered inn silhouette. "
            "Soft only. No slogans, no protest, not the subject."
        )

    return "\n".join(parts)


def get_locale_product_lock(place: dict, activity_key: str) -> str:
    """Harder local-language product/sign locks for kiosk + eat_local + cinema."""
    if activity_key not in {"kiosk_stop", "eat_local", "cash_pay", "cinema_program"}:
        return ""
    cc = (place.get("country_code") or "").upper()
    name = place.get("name_en") or "here"
    if activity_key == "kiosk_stop":
        return (
            f"\nKIOSK LOCALE LOCK ({cc}): newspaper mastheads, cigarette packs, lottery tickets, bottle labels, "
            f"and price stickers in local language for {name} — readable if close. "
            "No English tourist magazines as the hero text unless US/UK/IE/AU/NZ/CA."
        )
    if activity_key == "eat_local":
        return (
            f"\nEAT LOCAL LOCALE LOCK ({cc}): food wrapping, paper cone, napkin stamp, or chalkboard "
            f"in local language for {name}. The dish itself must read as local — not generic burger."
        )
    if activity_key == "cinema_program":
        return (
            f"\nCINEMA LOCALE LOCK ({cc}): program board / posters for {name} — titles and times in local "
            "language where that cinema would; ≥1 local production readable. Not English-only Hollywood lobby cards."
        )
    return (
        f"\nCASH LOCALE LOCK ({cc}): local currency for {name} clearly implied — worn notes/coins of that country."
    )


def resolve_canonical_reference(
    character_key: str,
    exploit_key: str | None = None,
    context: str = "land",
) -> bytes:
    """Ingrid back exploits: use jacket-back reference so falcon graphic matches."""
    if (
        character_key == "ingrid"
        and exploit_key in INGRID_BACK_EXPLOIT_KEYS
        and INGRID_FALCON_JACKET_REF.exists()
    ):
        return INGRID_FALCON_JACKET_REF.read_bytes()
    return load_exploit_canonical(character_key, exploit_key) or load_canonical(character_key, context=context)


