def get_kinky_light_outfit_lock(
    character_key: str,
    activity_key: str | None = None,
    place: dict | None = None,
    *,
    nightlife_mode: bool = False,
    noir_mode: bool = False,
    eclipse_mode: bool = False,
    viper_mode: bool = False,
    maxpower_mode: bool = False,
) -> str:
    """Fetish-light wardrobe — only true night register (nightlife or noir MAIN).

    eclipse/viper/maxpower may still color mood/lighting, but alone they must NOT
    swap day travel kit for leather-skirt kink (Stavanger golden-hour bug).
    Never activities.
    """
    note = CHARACTER_KINKY_LIGHT_OUTFIT.get(character_key)
    if not note:
        return ""
    # Only main hero — not stretch/laundromat/car_exit/activities
    if activity_key:
        return ""
    # Explicit night register only — not eclipse/viper/maxpower alone on a day main
    if not (nightlife_mode or noir_mode):
        return ""
    return (
        "OUTFIT OVERRIDE (MANDATORY — fetish-light MAIN only — NOT dungeon): "
        f"{note} "
        "Follow the character note exactly — do NOT substitute day jeans, denim/cutoff shorts, "
        "sneakers-as-day-kit, cream pantsuit, or quiet travel casual. "
        "No harness, no collar, no open BDSM staging."
    )


_OUTFIT_SLASH_GROUP_RE = re.compile(
    r"\(([a-z][a-z0-9\s\-]+(?:/[a-z][a-z0-9\s\-]+)+)\)",
    re.IGNORECASE,
)


def _pin_outfit_choices(text: str) -> str:
    """Resolve deliberate 'A OR B' and (white/grey/black) once per place-set."""
    pinned = text
    # Capital OR only — wardrobe alternatives in CHARACTER_DAY_OUTFIT (not prose "or")
    for _ in range(12):
        i = pinned.find(" OR ")
        if i < 0:
            break
        left_boundary = max(
            pinned.rfind(", ", 0, i),
            pinned.rfind("; ", 0, i),
            pinned.rfind(". ", 0, i),
            pinned.rfind(": ", 0, i),
            pinned.rfind("— ", 0, i),
            pinned.rfind("(", 0, i),
        )
        if left_boundary < 0:
            left_start = 0
        elif pinned[left_boundary] == "(":
            left_start = left_boundary + 1
        else:
            left_start = left_boundary + 2
        right_ends = [
            x for x in (
                pinned.find(", ", i + 4),
                pinned.find("; ", i + 4),
                pinned.find(". ", i + 4),
                pinned.find("— ", i + 4),
                pinned.find(")", i + 4),
            )
            if x >= 0
        ]
        right_end = min(right_ends) if right_ends else len(pinned)
        left = pinned[left_start:i].strip()
        right = pinned[i + 4:right_end].strip()
        before = pinned[max(0, left_start - 10):left_start].upper()
        if "NOT " in before or left.upper().startswith("NOT "):
            pinned = pinned[:i] + " / " + pinned[i + 4:]
            continue
        if not left or not right or len(left) > 90 or len(right) > 90:
            pinned = pinned[:i] + " / " + pinned[i + 4:]
            continue
        pick = random.choice([left, right])
        pinned = pinned[:left_start] + pick + pinned[right_end:]

    def _slash_pick(m: re.Match) -> str:
        opts = [p.strip() for p in m.group(1).split("/") if p.strip()]
        return random.choice(opts) if opts else m.group(0)

    return _OUTFIT_SLASH_GROUP_RE.sub(_slash_pick, pinned)


