def _miles_day_outfit_for_place(place: dict) -> str:
    """Rare shirtless for Miles — sticky per place-set. Never in towns/cities; cool north clothed."""
    if is_northern_pulli_place(place):
        return _MILES_DAY_CLOTHED
    # Never bare-chest in settlements (any size) or urban place_types
    if is_urban_place(place) or _is_settlement_place(place):
        return _MILES_DAY_CLOTHED
    t = (place.get("terrain_type") or "").lower()
    pt = (place.get("place_type") or "").lower()
    # Soft rates — was ~0.22–0.52; cut hard (still desert-biased)
    if t == "desert" or pt in {"scenic_drive", "national_park", "natural_park", "nature_reserve"}:
        p = 0.22
    elif t in {"hills", "wilderness", "flatland", "lake"}:
        p = 0.12
    elif t in {"mountain", "high_mountains"}:
        p = 0.08
    else:
        p = 0.05
    return _MILES_DAY_SHIRTLESS if random.random() < p else _MILES_DAY_CLOTHED


