def _amber_day_outfit_for_place(place: dict) -> str:
    """Body+cutoffs = heat spice only; coastal prefers linen+jeans gold; casual/town elsewhere."""
    if is_northern_pulli_place(place) or requires_modest_wardrobe(place):
        return _AMBER_DAY_TOWN
    t = (place.get("terrain_type") or "").lower()
    pt = (place.get("place_type") or "").lower()
    urban = pt in {"city", "medium_town", "capital", "large_town"} or is_urban_place(place)
    coastalish = (
        t == "coastal"
        or pt in {"beach", "harbour", "harbor"}
        or is_beach_place(place)
        or is_shore_sand_context(place)
    )
    heat = (
        t == "desert"
        or pt in {"scenic_drive", "beach"}
        or (t == "coastal" and not urban)
        or is_beach_place(place)
        or is_shore_sand_context(place)
    )
    r = random.random()
    if coastalish:
        # Fort Pierce gold: linen+jeans ~40%, casual ~40%, body+cutoffs ~20%
        if r < 0.40:
            return _AMBER_DAY_COASTAL
        if r < 0.80:
            return _AMBER_DAY_CASUAL
        return _AMBER_DAY_BODY_SHORTS
    if heat:
        # body+shorts ~38%, casual ~47%, town/dress ~15%
        if r < 0.38:
            return _AMBER_DAY_BODY_SHORTS
        if r < 0.85:
            return _AMBER_DAY_CASUAL
        return _AMBER_DAY_TOWN
    if urban:
        # body rare ~12%, casual ~38%, town ~50%
        if r < 0.12:
            return _AMBER_DAY_BODY_SHORTS
        if r < 0.50:
            return _AMBER_DAY_CASUAL
        return _AMBER_DAY_TOWN
    # hills/lake/mountain/small town — body ~22%
    if r < 0.22:
        return _AMBER_DAY_BODY_SHORTS
    if r < 0.62:
        return _AMBER_DAY_CASUAL
    return _AMBER_DAY_TOWN


