def _diana_day_outfit_for_place(place: dict) -> str:
    """Rotate tailored (Vlore gold), jeans kit, and coat — coat is not the default."""
    r = random.random()
    # ~40% tailored no-coat, ~35% jeans/top, ~25% coat
    if r < 0.40:
        return _DIANA_DAY_TAILORED
    if r < 0.75:
        return _DIANA_DAY_JEANS
    return _DIANA_DAY_COAT


def get_diana_noir_outfit() -> str:
    """Noir/main dark — ~45% tailored no-coat (Vlore), ~55% classic coat+gloves."""
    if random.random() < 0.45:
        return (
            "Black button-down blouse + high-waist tailored black trousers + thin black belt — "
            "coat OFF. Sleek black boots. Red lacquer lips. Small black bag optional. "
            "Unlit cigarette optional. Goth-elegant quiet luxury — NOT the leather-coat default."
        )
    return (
        "Long black leather coat, belted. Black leather opera gloves — one or both. "
        "Back-seam stockings. Black heels. Cigarette — unlit, between gloved fingers."
    )


def get_boulder_crash_pad_lock() -> str:
    """Outdoor boulder / boulder_hang — often no pad (~65%); pad is not the default prop."""
    if random.random() < 0.65:
        return (
            "\nCRASH PAD (THIS SHOT): NONE. Bare dirt / stone / scrub under the boulder only. "
            "No foam pad, no gym mat, no folded crash-pad in frame. Solo send, undeveloped landing."
        )
    return (
        "\nCRASH PAD (THIS SHOT): one thin outdoor crash pad on the landing OK — "
        "single pad, not a gym mat stack, not the subject of the frame."
    )


def ensure_day_outfit_sticky(character_key: str, place: dict) -> str | None:
    """Create/return pinned day look for this place-set (even if this shot skips applying it)."""
    if character_key == "miles":
        base = _miles_day_outfit_for_place(place)
    elif character_key == "amber":
        base = _amber_day_outfit_for_place(place)
    elif character_key == "alessandra":
        base = _alessandra_day_outfit_for_place(place)
    elif character_key == "diana":
        base = _diana_day_outfit_for_place(place)
    else:
        base = CHARACTER_DAY_OUTFIT.get(character_key)
    if not base:
        return None
    key = _day_outfit_sticky_key(character_key, place)
    cached = _DAY_OUTFIT_STICKY.get(key)
    if cached:
        return cached
    pinned = _pin_outfit_choices(base)
    # katja: COOL/Norweger already in CHARACTER_SPECS cool block — skip soft pulli (was 2× Mariusgenser)
    _pulli = (
        ""
        if character_key == "katja"
        else get_northern_pulli_lock(place, character_key)
    )
    _no_pulli = get_no_nordic_pulli_lock(place, character_key)
    if _no_pulli and character_key == "ingrid":
        pinned = (
            "Scandi day heat/south: athletic shorts or light pants, fitted tank or tee, trainers; "
            "Falcon leather open or carried — NO Norwegian Pulli / Mariusgenser / thick geometric wool."
        )
    _pulli_bit = f" {_pulli}" if _pulli else ""
    _no_pulli_bit = f" {_no_pulli}" if _no_pulli else ""
    text = (
        f"DAY OUTFIT LOCK (same clothes for this place-set — PINNED, do not re-roll): {pinned} "
        "EXACT same garments in every day/street/cafe/main shot here — same top, same bottoms, "
        "same shoes/boots, same colors. Do not switch jeans↔shorts or invent a new look mid-set. "
        "Ignore '~15% WARDROBE VARIANT' / rotating options in the character brief for this set. "
        "Hike, swim, run, SUP may still replace this when those activities fire. "
        "At the vehicle: keep THIS kit (jacket layer ok if road lock requires). "
        "DAYTIME — normal travel clothes only. No fetish-light / nightlife kink."
        f"{_pulli_bit}{_no_pulli_bit}"
    )
    _DAY_OUTFIT_STICKY[key] = text
    return text


def get_day_outfit_override(
    character_key: str, place: dict, activity_key: str | None = None,
) -> str | None:
    """Sticky primary day look for this place-set — skip when special kits apply. No kink."""
    sticky = ensure_day_outfit_sticky(character_key, place)
    if not sticky:
        return None
    act = activity_key or ""
    if act in _DAY_OUTFIT_SKIP_ACTIVITIES or act in _VEHICLE_TRAVEL_OUTFIT_ACTIVITIES:
        return None
    # _SWIM_OUTFIT_ACTIVITIES defined later in module — resolve at call time
    _swim = globals().get("_SWIM_OUTFIT_ACTIVITIES") or frozenset()
    if act in _swim:
        return None
    if is_shore_sand_context(place):
        return f"{sticky}\n{SHORE_FOOTWEAR_LOCK}"
    if (place.get("terrain_type") or "") == "coastal":
        return f"{sticky}\n{COASTAL_SAND_FEET_LOCK}"
    return sticky


def get_day_outfit_continuity(character_key: str, place: dict) -> str:
    """Append to road/vehicle shots so car moments keep the pinned day kit."""
    sticky = ensure_day_outfit_sticky(character_key, place)
    if not sticky:
        return ""
    # Drop the long day preamble — keep the pinned garments + hard continuity
    body = sticky
    for prefix in (
        "DAY OUTFIT LOCK (same clothes for this place-set — PINNED, do not re-roll): ",
        "DAY OUTFIT LOCK (same clothes for this place-set): ",
    ):
        if body.startswith(prefix):
            body = body[len(prefix):]
            break
    return (
        "SET WARDROBE CONTINUITY (MANDATORY at vehicle): same pinned day clothes as this place-set — "
        f"{body} "
        "Do NOT invent a new outfit at the car. Same top/bottoms/shoes; jacket only if road lock requires."
    )


