def get_character_water_outfit(
    character_key: str, place: dict | None = None, activity_key: str | None = None,
) -> str:
    """Swim lock for beach/SUP/lake. CHARACTER_SWIM_OUTFIT wins alone when set (coherence).
    Kelek: western one-shoulder default; North Africa → modest burkini-style.
    Werra: dark grey technical kit preferred in Nordics / Scotland / North Sea.
    Metka: black one-piece preferred in colder northern / Baltic water.
    Tammy: dark grey technical one-piece on SUP/paddle; black ribbed bralette bikini on shore."""
    if character_key == "kelek" and place:
        cc = (place.get("country_code") or "").upper()
        if cc in _KELEK_NORTH_AFRICA_CC:
            return KELEK_SWIM_OUTFIT_MAGHREB
    if character_key == "werra" and place:
        cc = (place.get("country_code") or "").upper()
        name = (place.get("name_en") or "").lower()
        if cc in _WERRA_COLD_NORTH_CC or any(
            x in name for x in ("fjord", "scotland", "orkney", "shetland", "hebrid", "faroe")
        ):
            return WERRA_SWIM_OUTFIT_COLD_NORTH
    if character_key == "metka" and place:
        cc = (place.get("country_code") or "").upper()
        terrain = (place.get("terrain_type") or "").lower()
        name = (place.get("name_en") or "").lower()
        if cc in _METKA_COLD_WATER_CC or terrain in {"lake", "mountain", "high_mountains"} or any(
            x in name for x in ("fjord", "baltic", "north sea")
        ):
            return METKA_SWIM_OUTFIT_COLD
    if character_key == "tammy" and (activity_key or "") in _TAMMY_ACTIVE_WATER_ACTIVITIES:
        return TAMMY_SWIM_OUTFIT_ACTIVE
    swim = (CHARACTER_SWIM_OUTFIT.get(character_key) or "").strip()
    if swim:
        return swim
    return _extract_beach_from_spec(CHARACTER_SPECS.get(character_key, ""))


def get_sup_outfit_override(
    character_key: str, activity_key: str | None = None, place: dict | None = None,
) -> str:
    body = get_character_water_outfit(character_key, place, activity_key=activity_key)
    if not body:
        if character_key in MALE_CHARACTERS:
            body = (
                "PRIMARY: plain dark board shorts or swim trunks. Bare chest or thin tee off. "
                "Barefoot. NO jeans, NO windbreaker, NO street shoes, NO jacket on the board."
            )
        else:
            body = (
                "light outdoor swimwear — bikini, one-piece, or bikini top with boardshorts"
            )
    rash = ""
    # Tammy active = grey one-piece already; skip rashguard roll
    if (
        character_key != "tammy"
        and activity_key in _SUP_RASHGUARD_ACTIVITIES
        and random.random() < _SUP_RASHGUARD_P
    ):
        rash = (
            _SUP_RASHGUARD_LOCK_M if character_key in MALE_CHARACTERS else _SUP_RASHGUARD_LOCK_F
        ) + " "
        if _char_select_verbose:
            print(f"  👕 SUP rashguard roll — {character_key} / {activity_key}")
    return (
        f"{rash}"
        "SUP OUTFIT (MANDATORY — character BEACH/SWIM spec; overrides generic kajak_sup text, "
        "reference-image street clothes, prestige/noir/sidewinder wardrobe, and any default sport bikini): "
        f"{body} "
        "Barefoot on SUP. No cover-up, coat, blazer, jeans, windbreaker, or gloves on the board."
        + (
            " Rashguard covers the upper body this shot — do not drop to bikini/bare chest."
            if rash
            else ""
        )
    )


def get_character_water_outfit_override(
    character_key: str, place: dict | None = None, activity_key: str | None = None,
) -> str | None:
    body = get_character_water_outfit(character_key, place, activity_key=activity_key)
    if not body:
        return None
    return (
        "SWIM/BEACH OUTFIT (MANDATORY — overrides reference image, urban wardrobe, and BEACH LIGHT defaults): "
        f"{body}"
    )


