def is_heritage_site(place: dict | None) -> bool:
    """Ruins / pyramids / CLEO period sites — even when DB says nature_reserve."""
    if not place:
        return False
    name = _place_name_en(place)
    if name in CLEO_PERIOD_HINTS:
        return True
    pt = (place.get("place_type") or "").lower()
    if pt in _HERITAGE_PLACE_TYPES or "historic" in pt or "archaeol" in pt or "heritage" in pt:
        return True
    nl = name.lower()
    return any(s in nl for s in _HERITAGE_NAME_SUBSTRINGS)


def heritage_activity_ok(place: dict | None, activity_key: str) -> bool:
    if not activity_key or not is_heritage_site(place):
        return True
    return activity_key not in _HERITAGE_BLOCKED_ACTIVITIES


