def get_dog_companion_note(character_key: str, place: dict, activity_key: str = "", premium_mode: bool = False, dayhike_mode: bool = False) -> str:
    """Loose, non-mandatory companion-dog appearance — random base rate (CAST dog_prob),
    modulated by activity/terrain/premium-layer context. Empty string most of the time."""
    cast = CAST.get(character_key)
    if not cast or not cast.get("dog"):
        return ""
    if (character_key, activity_key) in _DOG_SKIP_CHAR_ACTIVITY:
        return ""
    if premium_mode or activity_key in _DOG_EXCLUDE_ACTIVITIES:
        return ""
    dog_name = cast["dog"]
    prob = cast.get("dog_prob", 0.4)
    if activity_key in _DOG_BOOST_ACTIVITIES or dayhike_mode:
        prob *= 1.4
    elif place.get("terrain_type", "") in _DOG_OUTDOOR_TERRAIN:
        prob *= 1.15
    prob = min(prob, 0.9)
    if random.random() >= prob:
        return ""
    breed = DOG_BREED_DESC.get(dog_name, dog_name)
    if character_key == "sofia" and dog_name == "goldie":
        beat = random.choice([
            "Goldie already chose the best spot and is waiting like she owns it.",
            "Goldie half a step ahead — Sofia follows without arguing.",
            "Goldie settled first; Sofia is still deciding.",
        ])
        return (
            f"\nDOG COMPANION (present — Goldie): {breed}. Red collar. Rose-folded ears always. "
            f"MICRO-BEAT: {beat} Natural, not staged. No other breed."
        )
    if character_key == "jack_mae" and dog_name == "goldie":
        beat = random.choice([
            "Goldie waits at the porch edge or pickup wheel — calm, not begging for the frame.",
            "Goldie lies nearby while Jack and Mae read the place — never the subject.",
            "Goldie quietly explores a few steps away — travelling companion, not a pose prop.",
        ])
        return (
            "\nDOG COMPANION (present — Goldie): mature golden retriever, thick honey-colored coat. "
            f"MICRO-BEAT: {beat} Never centre of attention. Not a Podenco. No other breed."
        )
    if character_key == "jonas_lara" and dog_name == "flocke":
        beat = random.choice([
            "Flocke waits by the Volvo or sits at frame edge — calm, alert, not performing.",
            "Flocke nearby while Jonas and Lara read the site — never the subject.",
            "Flocke quietly watches the same direction they are looking — companion, not prop.",
        ])
        return (
            "\nDOG COMPANION (present — Flocke): golden retriever, light honey coat, black collar. "
            f"MICRO-BEAT: {beat} Never centre of attention. Not a desert mixed-breed. No other breed."
        )
    if character_key == "djordje" and dog_name == "roki":
        return (
            f"\nDOG COMPANION (present — Roki): {breed}. "
            "MICRO-BEAT: Roki half in frame or at Djordje's heel — Djordje does not look at him, "
            "does not pet him, does not acknowledge him. Balkan indifference; the dog stays anyway. "
            "No other breed."
        )
    return (
        f"\nDOG COMPANION (present in this shot): {dog_name} — {breed}. "
        f"Natural presence beside {character_key.capitalize()}, not staged, on leash or off-leash as fits the setting. "
        f"If shown, must match this description exactly — no other breed, no substitution."
    )

