# Rough EU/Europe bucket for CAST geo lookup — v1 simplification, per-country pools deferred.
_CAST_EU_CC = {
    "DE", "AT", "CH", "FR", "IT", "ES", "PT", "GR", "GB", "IE", "BE", "NL", "LU",
    "DK", "SE", "NO", "FI", "IS", "PL", "CZ", "SK", "HU", "RO", "BG", "HR", "SI",
    "ME", "AL", "MK", "RS", "BA", "LV", "LT", "EE", "MC", "TR", "GE", "AM", "CY", "MT",
}
_CAST_US_CC = {"US", "CA", "MX"}  # North America bucket for continent split (MX with US cast)

_char_select_verbose = False


def _cast_geo_region(country_code: str) -> str:
    if country_code in _CAST_EU_CC:
        return "eu"
    if country_code in _CAST_US_CC:
        return "us"
    return ""  # neither bucket — continent multiplier stays 1.0 (LatAm etc. via REGION_CORE)


def _cast_continent_weight(char: str, country_code: str) -> float:
    """CAST.geo as continent gate: home ≈ 1.0, guest = guest/home (≪1), 0 = hard block.
    Charlotte keeps full guest ratio (exception); other guests get an extra squash."""
    region = _cast_geo_region(country_code)
    if not region:
        return 1.0
    geo = (CAST.get(char) or {}).get("geo") or {}
    w = float(geo.get(region, 0) or 0)
    if w <= 0:
        return 0.0
    home = max(float(geo.get("eu", 0) or 0), float(geo.get("us", 0) or 0), 1e-6)
    ratio = w / home
    if 0 < ratio < 1.0 and char not in {"charlotte", "stacy"}:
        ratio *= 0.5  # sharper split — charlotte/stacy keep their CAST.geo guest ratio
    return ratio


def _terrain_class(terrain_type: str, place_type: str) -> str:
    if terrain_type == "coastal":
        return "coastal"
    if terrain_type == "lake":
        return "lake"
    if terrain_type in ("mountain", "mountains", "high_mountains", "hills"):
        return "mountain"
    if terrain_type == "desert":
        return "desert"
    if (place_type or "").lower() == "city":
        return "city"
    return "*"


