# ── Soft geo affinity — Character Rules v2 (+ legacy lanes for active chars not in v2)
# Nudges only. role: workhorse | specialist | sparse
# perfect_places / crossover_places = name_en; require_landscape = bucket allow-list
_MED_BEACH_CC = frozenset({
    "ES", "PT", "FR", "IT", "GR", "HR", "ME", "AL", "TR", "CY", "MT", "MC",
    "SI", "BA", "TN", "MA", "DZ", "EG", "IL", "LB",
})
_CARIBBEAN_CC = frozenset({
    "CU", "JM", "HT", "DO", "PR", "TT", "BB", "LC", "VC", "GD", "AG", "DM", "KN", "BS",
})
_AFFINITY_PERFECT = 1.35
_AFFINITY_PERFECT_PLACE = 1.55
_AFFINITY_OK = 1.08
_AFFINITY_CROSSOVER = 1.30
_AFFINITY_NEVER_CC = 0.12
_AFFINITY_NEVER_LAND = 0.22
_AFFINITY_SPARSE = 0.50
_AFFINITY_NEVER_EU = 0.08
_AFFINITY_REQUIRE_LAND = 0.14
_AFFINITY_GUEST = 0.16  # outside perfect_places when strict_perfect_places


def _place_name_hit(pname: str, names: frozenset | set) -> bool:
    """Exact or substring place match (len≥4) — 'Miami Beach' hits 'Miami'."""
    if not pname or not names:
        return False
    if pname in names:
        return True
    pl = pname.lower()
    for n in names:
        nl = (n or "").lower()
        if len(nl) < 4:
            continue
        if nl in pl or pl in nl:
            return True
    return False


def _affinity_multiplier(
    char: str,
    country_code: str,
    terrain_type: str = "",
    place_type: str = "",
    place_name: str = "",
) -> float:
    spec = CHAR_GEO_AFFINITY.get(char)
    if not spec:
        return 1.0
    cc = (country_code or "").upper()
    pname = place_name or ""
    bucket = _landscape_bucket(terrain_type, place_type, pname)
    m = 1.0
    never_places = spec.get("never_places") or frozenset()
    if _place_name_hit(pname, never_places):
        if spec.get("hard_never_places"):
            return 0.0
        m *= _AFFINITY_NEVER_CC
    perfect_places = spec.get("perfect_places") or frozenset()
    crossover_places = spec.get("crossover_places") or frozenset()
    in_crossover = _place_name_hit(pname, crossover_places)
    in_perfect_place = _place_name_hit(pname, perfect_places)
    if in_perfect_place:
        m *= _AFFINITY_PERFECT_PLACE
    elif in_crossover:
        m *= _AFFINITY_CROSSOVER
    # never_eu skipped for intentional crossover Easter eggs
    if spec.get("never_eu") and cc in _CAST_EU_CC and not in_crossover:
        m *= _AFFINITY_NEVER_EU
    never_cc = spec.get("never_cc") or frozenset()
    perfect = spec.get("perfect_cc") or frozenset()
    ok = spec.get("ok_cc") or frozenset()
    if not in_perfect_place and not in_crossover:
        if cc in never_cc:
            if spec.get("hard_never_cc"):
                return 0.0
            m *= _AFFINITY_NEVER_CC
        elif cc in perfect:
            m *= _AFFINITY_PERFECT
        elif cc in ok:
            m *= _AFFINITY_OK
        elif spec.get("strict_perfect_places") and cc not in perfect:
            # Named territory only (e.g. Isabella Atlantic NE) — rest is guest
            m *= float(spec.get("guest_factor", _AFFINITY_GUEST))
    never_land = spec.get("never_landscape") or frozenset()
    if bucket in never_land:
        m *= _AFFINITY_NEVER_LAND
    if spec.get("never_med_beach") and bucket == "beach" and cc in _MED_BEACH_CC:
        m *= _AFFINITY_NEVER_LAND
    never_coast = spec.get("never_coast_cc") or frozenset()
    if cc in never_coast and bucket in {"beach", "coastal", "harbour"}:
        m *= _AFFINITY_NEVER_LAND
    require_land = spec.get("require_landscape") or frozenset()
    if require_land and bucket not in require_land and not in_perfect_place:
        m *= _AFFINITY_REQUIRE_LAND
    if spec.get("role") == "sparse" and cc not in perfect and not in_perfect_place:
        m *= float(spec.get("sparse_factor", _AFFINITY_SPARSE))
    if char == "kelek" and cc not in _KELEK_HOME_CC:
        if cc in _KELEK_NEAR_CC:
            m *= 0.28
        else:
            m *= 0.07
    return m


