def _apply_char_geo_affinity(
    weights: dict[str, float],
    country_code: str,
    terrain_type: str = "",
    place_type: str = "",
    place_name: str = "",
) -> dict[str, float]:
    if not weights:
        return weights
    out = {}
    for k, v in weights.items():
        if v <= 0:
            continue
        mv = (
            v
            * _affinity_multiplier(k, country_code, terrain_type, place_type, place_name)
            * _cast_continent_weight(k, country_code)
        )
        if mv > 0.0001:
            out[k] = mv
    return out  # empty = caller falls back; never restore continent-blocked weights


