def _landscape_bucket(terrain_type: str, place_type: str, place_name: str = "") -> str:
    """Coarse place/landscape class for cast intelligence."""
    pt = (place_type or "").lower()
    ptu = (place_type or "").upper()
    name = (place_name or "").lower()
    t = (terrain_type or "").lower()

    if (
        pt == "beach"
        or ptu in {"BCH"}
        or any(k in name for k in ("beach", "strand", "plage", "playa", "spiaggia"))
    ):
        return "beach"
    if (
        pt in {"harbour", "harbor", "port"}
        or ptu in {"HBR", "PRT"}
        or any(k in name for k in ("harbour", "harbor", "hafen", "porto", "liman"))
    ):
        return "harbour"
    if t == "desert" or pt == "desert" or ptu in {"DSRT", "DSR", "DUNE"}:
        return "desert"
    if t in {"mountain", "mountains", "high_mountains", "hills"} or ptu in {"MNTN", "MT", "MTS", "PKS"}:
        return "alpine"
    if (
        pt in {"national_park", "wilderness", "nature_reserve", "natural_park"}
        or ptu in {"PRK", "PRKX", "NPARK", "RESV"}
    ):
        return "nature_park"
    if t == "lake" or ptu in {"LK", "LKS", "LKI", "RSV"}:
        return "lake"
    if pt in {"city", "medium_town"} or ptu in {"PPLC", "PPLA"}:
        return "urban"
    if pt in {"village", "hamlet", "small_town", "isolated_dwelling"}:
        return "village"
    if pt == "scenic_drive" or "scenic" in name or "pass" in name:
        return "scenic"
    if t == "coastal":
        return "coastal"
    return "generic"


def _lookup_region_core(
    country_code: str,
    terrain_type: str,
    place_type: str,
    place_name: str = "",
) -> tuple[dict[str, float], str]:
    """Regional core + landscape blend. Empty dict → randoms only."""
    cls = _terrain_class(terrain_type, place_type)
    group = _POOL_GROUP.get(country_code, "default")
    core: dict[str, float] = {}
    for c in (cls, "*"):
        if (group, c) in REGION_CORE:
            core = dict(REGION_CORE[(group, c)])
            break
    rot_key = get_rotation_key(country_code, terrain_type, place_type)
    if rot_key in CORE_KEY_BOOST:
        core = {**core, **CORE_KEY_BOOST[rot_key]}
    # Landscape / place_type pull (beach, NP, desert, urban, …)
    bucket = _landscape_bucket(terrain_type, place_type, place_name)
    for k, v in LANDSCAPE_CORE.get(bucket, {}).items():
        if k == "kelek" and country_code not in _KELEK_HOME_CC:
            continue
        core[k] = core.get(k, 0) + v * LANDSCAPE_CORE_BLEND
    _pt = (place_type or "").lower()
    _beachy = cls == "coastal" or bucket == "beach" or _pt == "beach"
    _bro_ok = (
        (place_name or "") in _CHAD_BRO_SCENE_PLACES
        or (place_name or "") in _CHAD_HYPE_PLACES
    )
    if country_code in _CHAD_HYPE_CC and not (_beachy and not _bro_ok):
        core["chad"] = max(core.get("chad", 0), _CHAD_HYPE_CC_SHARE)
    # Named magnets from affinity (Key West→Tasha, Roswell→Werra/Tammy, Boston→Charlotte, …)
    _pname = place_name or ""
    _magnet = False
    for _char, _spec in CHAR_GEO_AFFINITY.items():
        if _char in DISABLED_CHARACTERS:
            continue
        if _pname in (_spec.get("perfect_places") or ()):
            core[_char] = max(core.get(_char, 0), 0.48)
            _magnet = True
        elif _pname in (_spec.get("crossover_places") or ()):
            core[_char] = max(core.get(_char, 0), 0.30)
            _magnet = True
    label = f"{group}/{cls}/{bucket}"
    if country_code in _CHAD_HYPE_CC and not (_beachy and not _bro_ok):
        label += "+chad_hype"
    if _magnet:
        label += "+magnet"
    return core, label


def _char_eligible(name: str, char: dict, cls: str, ctx: dict) -> bool:
    if name in DISABLED_CHARACTERS:
        return False
    terrain_ok = char.get("terrain") is None or cls == "*" or cls in (char.get("terrain") or [])
    if not terrain_ok:
        return False
    if name == "valentina" and not valentina_allowed(ctx):
        return False
    if name == "regina" and not regina_allowed(ctx):
        return False
    return True


def _random_cast_pool(
    country_code: str,
    terrain_type: str,
    place_type: str,
    ctx: dict,
    exclude: set[str] | None = None,
) -> list[str]:
    """Eligible random candidates (core excluded); landscape weighting applied separately."""
    cls = _terrain_class(terrain_type, place_type)
    exclude = exclude or set()
    bucket = _landscape_bucket(terrain_type, place_type, ctx.get("name_en", ""))
    _beachy = bucket == "beach" or cls == "coastal"
    out: list[str] = []
    for name, char in CAST.items():
        if name in exclude:
            continue
        if not _char_eligible(name, char, cls, ctx):
            continue
        if name == "metka" and country_code not in _METKA_HOME_CC and _beachy:
            continue
        if name == "djordje" and country_code not in _DJORDJE_HOME_CC:
            continue
        # Jelena: Balkan home density via REGION_CORE / Balkan street pool — EU guest ok (no home_cc hard block)
        if name == "naomi" and country_code in _NAOMI_THROTTLE_CC:
            continue
        if name == "kelek" and country_code not in _KELEK_HOME_CC:
            continue
        if name == "chad" and _beachy:
            pname = ctx.get("name_en") or ""
            if pname not in _CHAD_BRO_SCENE_PLACES and pname not in _CHAD_HYPE_PLACES:
                continue
        out.append(name)
    return out


def _random_cast_weights(
    country_code: str,
    terrain_type: str,
    place_type: str,
    ctx: dict,
    exclude: set[str] | None = None,
) -> dict[str, float]:
    """Random pool with landscape intelligence: fit ×3, odd ×0.35, else ×1."""
    bucket = _landscape_bucket(terrain_type, place_type, ctx.get("name_en", ""))
    fit = LANDSCAPE_FIT.get(bucket, frozenset())
    odd = LANDSCAPE_ODD.get(bucket, frozenset())
    w: dict[str, float] = {}
    for name in _random_cast_pool(country_code, terrain_type, place_type, ctx, exclude=exclude):
        if name in fit:
            w[name] = 3.0
        elif name in odd:
            w[name] = 0.35
        else:
            w[name] = 1.0
    return w


def _draw_from_pool(pool: dict, ctx: dict, label: str) -> str:
    w = {}
    for char, weight in pool.items():
        if char in DISABLED_CHARACTERS or weight <= 0:
            continue
        if char == "valentina" and not valentina_allowed(ctx):
            continue
        if char == "regina" and not regina_allowed(ctx):
            continue
        if char not in CAST:
            continue
        w[char] = weight
    if not w:
        w = {"sofia": 1.0}
    total = sum(w.values())
    w = {k: v / total for k, v in w.items()}
    char = random.choices(list(w), weights=list(w.values()), k=1)[0]
    if _char_select_verbose:
        print(f"  🎭 char={char} ({w[char]*100:.0f}%) — pool {label}")
    return char


def _cast_pool(
    country_code: str,
    terrain_type: str,
    place_type: str,
    place_name: str = "",
) -> tuple[dict, str]:
    """Effective pick probabilities for sims: CORE_PICK_P·core + (1-p)·landscape-weighted randoms."""
    ctx = {
        "name_en": place_name,
        "country_code": country_code,
        "terrain_type": terrain_type or "",
        "place_type": place_type or "",
        "attractiveness_score": 0,
    }
    core, label = _lookup_region_core(country_code, terrain_type, place_type, place_name)
    cls = _terrain_class(terrain_type, place_type)
    core = {
        k: v for k, v in core.items()
        if v > 0 and k in CAST and _char_eligible(k, CAST[k], cls, ctx)
    }
    core = _apply_char_geo_affinity(core, country_code, terrain_type, place_type, place_name)
    rw = _random_cast_weights(country_code, terrain_type, place_type, ctx, exclude=set(core))
    rw = _apply_char_geo_affinity(rw, country_code, terrain_type, place_type, place_name)
    weights: dict[str, float] = {}
    if core:
        ctot = sum(core.values())
        for k, v in core.items():
            weights[k] = CORE_PICK_P * (v / ctot)
    if rw:
        share = (1.0 - CORE_PICK_P) if core else 1.0
        rtot = sum(rw.values())
        for k, v in rw.items():
            weights[k] = weights.get(k, 0) + share * (v / rtot)
    if not weights:
        weights = {"sofia": 1.0}
    return weights, f"core+random/{label}"


def select_character(country_code: str, terrain_type: str, place_type: str, place_name: str = "", place: dict | None = None) -> str:
    ctx = place or {
        "name_en": place_name,
        "country_code": country_code,
        "terrain_type": terrain_type or "",
        "place_type": place_type or "",
        "attractiveness_score": 0,
    }

    # 1. Forced places (dict pools still respect continent gate — comedy 100% strings do not)
    forced = FORCED_PLACES.get(place_name)
    if forced is not None:
        if isinstance(forced, str):
            if _char_select_verbose:
                print(f"  🎭 char={forced} — forced place: {place_name}")
            return forced
        pool = _apply_char_geo_affinity(
            dict(forced), country_code, terrain_type, place_type, place_name,
        )
        if not pool:
            pool = dict(forced)
        return _draw_from_pool(pool, ctx, f"forced:{place_name}")

    terrain_type = guess_terrain(terrain_type, place_type)
    place_name = place_name or ctx.get("name_en", "")

    # 2. Road POV — separate from cast
    _road_pov = try_road_pov(country_code, terrain_type, place_type, place_name)
    if _road_pov:
        return _road_pov

    # 3. Nature wildcard — 9%: city char out of element (intentional discomfort)
    global _nature_wildcard_char
    _nature_wildcard_char = None
    rot_key = get_rotation_key(country_code, terrain_type, place_type)
    if rot_key in NATURE_ROTATION_KEYS and random.random() < NATURE_WILDCARD_CHANCE:
        _pool = [c for c in NATURE_WILDCARD_CHARS if c not in DISABLED_CHARACTERS]
        # Weight by continent gate — home ≫ guest; Charlotte still crosses more than other EU
        _w = {c: _cast_continent_weight(c, country_code) for c in _pool}
        _w = {c: w for c, w in _w.items() if w > 0}
        if _w:
            _nature_wildcard_char = random.choices(list(_w), weights=list(_w.values()), k=1)[0]
            if _char_select_verbose:
                print(f"  🎭 char={_nature_wildcard_char} — nature wildcard ({rot_key})")
            return _nature_wildcard_char

    # 4. Core (region + landscape) OR landscape-weighted randoms
    core, label = _lookup_region_core(country_code, terrain_type, place_type, place_name)
    cls = _terrain_class(terrain_type, place_type)
    if is_diaz_border_place(ctx) and "diaz" not in DISABLED_CHARACTERS:
        core = {**core, "diaz": max(core.get("diaz", 0), 0.55)}
        label += "+diaz_border"
    core = {
        k: v for k, v in core.items()
        if v > 0 and k in CAST and _char_eligible(k, CAST[k], cls, ctx)
    }
    core = _apply_char_geo_affinity(core, country_code, terrain_type, place_type, place_name)

    if core and random.random() < CORE_PICK_P:
        return _draw_from_pool(core, ctx, f"core:{label}")

    rw = _random_cast_weights(country_code, terrain_type, place_type, ctx, exclude=set(core))
    rw = _apply_char_geo_affinity(rw, country_code, terrain_type, place_type, place_name)
    if not rw:
        rw = _random_cast_weights(country_code, terrain_type, place_type, ctx, exclude=set())
        rw = _apply_char_geo_affinity(rw, country_code, terrain_type, place_type, place_name)
    if not rw:
        return _draw_from_pool(core or {"sofia": 1.0}, ctx, f"fallback:{label}")
    return _draw_from_pool(rw, ctx, f"random:{label}")


def sample_character_candidates(
    place: dict, n: int = 5, *, fringe: bool = True,
) -> list[tuple[str, float, str]]:
    """Top-N by weight + optional one random fringe char. Each tuple: (name, p, kind)."""
    name = place.get("name_en") or ""
    cc = place.get("country_code") or ""
    terrain = guess_terrain(place.get("terrain_type") or "", place.get("place_type") or "")
    pt = place.get("place_type") or ""
    forced = FORCED_PLACES.get(name)
    if isinstance(forced, str):
        return [(forced, 1.0, "top")]
    if isinstance(forced, dict):
        pool = {
            k: float(v) for k, v in forced.items()
            if v > 0 and k in CAST and k not in DISABLED_CHARACTERS
        }
    else:
        pool, _ = _cast_pool(cc, terrain, pt, name)
        if is_diaz_border_place(place) and "diaz" not in DISABLED_CHARACTERS:
            pool = {**pool, "diaz": max(pool.get("diaz", 0.0), 0.55)}
    pool = {k: v for k, v in pool.items() if v > 0 and k not in DISABLED_CHARACTERS}
    if not pool:
        return [("sofia", 1.0, "top")]
    total = sum(pool.values())
    ranked = sorted(
        ((k, v / total) for k, v in pool.items()),
        key=lambda x: x[1],
        reverse=True,
    )
    top = [(k, p, "top") for k, p in ranked[:n]]
    if fringe and len(ranked) > n:
        rest = ranked[n:]
        # Fringe: uniform random among non-top (true left-field, not still-weighted)
        fk, fp = random.choice(rest)
        top.append((fk, fp, "fringe"))
    return top


def prompt_pick_character(place: dict, n: int = 5) -> str:
    """Interactive: top-N by weight + 1 random fringe; return chosen character key."""
    cands = sample_character_candidates(place, n=n, fringe=True)
    pname = place.get("name_en") or "?"
    cc = place.get("country_code") or "?"
    terrain = place.get("terrain_type") or "?"
    pt = place.get("place_type") or "?"
    landscape = _landscape_bucket(terrain if terrain != "?" else "", pt if pt != "?" else "", pname)
    rec = cands[0][0]
    rec_p = cands[0][1]
    print(f"\n  🎭 Pick cast for {pname} ({cc}):")
    print(f"     place_type={pt}  terrain={terrain}  landscape={landscape}")
    print(f"     ★ recommended: {rec}  (~{rec_p * 100:.0f}% — highest weight for this place)")
    for i, (char, p, kind) in enumerate(cands, 1):
        blurb = (CHARACTER_BODY_ANCHORS.get(char) or "").split("—")[0].strip()
        if len(blurb) > 72:
            blurb = blurb[:69] + "..."
        suffix = f" — {blurb}" if blurb else ""
        if kind == "fringe":
            tag = "  ✦ fringe"
        elif i == 1:
            tag = f"  (~{p * 100:.0f}%) ★"
        else:
            tag = f"  (~{p * 100:.0f}%)"
        print(f"     {i}) {char}{tag}{suffix}")
    print(f"     Enter 1–{len(cands)}, char name, or Enter={rec} (recommended)")
    if not sys.stdin.isatty():
        print(f"  🎭 non-TTY — auto {cands[0][0]}")
        return cands[0][0]
    while True:
        try:
            raw = input("  → ").strip()
        except EOFError:
            return cands[0][0]
        if not raw:
            return cands[0][0]
        if raw.isdigit():
            idx = int(raw)
            if 1 <= idx <= len(cands):
                return cands[idx - 1][0]
            print(f"     pick 1–{len(cands)}")
            continue
        key = _norm_key(raw)
        if key and key in {c for c, _, _ in cands}:
            return key
        if key and key in CAST and key not in DISABLED_CHARACTERS:
            return key
        print("     invalid — number, listed name, or Enter")


