TARGET_W, TARGET_H, TARGET_KB = 800, 1200, 110
LANDSCAPE_TARGET_W, LANDSCAPE_TARGET_H = 1200, 675  # 16:9


def _power_aura_subject_center(arr) -> tuple[float, float]:
    """Centroid of dark central mass (Regina's black coat) — ripples must start from her, not sky."""
    import cv2
    import numpy as np

    h, w = arr.shape[:2]
    gray = cv2.cvtColor(arr, cv2.COLOR_RGB2GRAY)
    x0, x1 = int(w * 0.25), int(w * 0.75)
    y0, y1 = int(h * 0.10), int(h * 0.90)
    roi = gray[y0:y1, x0:x1]
    # Black coat / silhouette — ignore bright sky/street
    mask = ((roi < 75) & (roi > 8)).astype(np.float32)
    if float(mask.sum()) < 800:
        return w / 2.0, h * 0.48
    ys_i, xs_i = np.mgrid[y0:y1, x0:x1]
    cx = float((xs_i * mask).sum() / mask.sum())
    cy = float((ys_i * mask).sum() / mask.sum())
    # Bias slightly up toward chest (centroid alone sits too low on legs)
    cy = cy * 0.72 + (y0 + (y1 - y0) * 0.38) * 0.28
    return cx, cy


def apply_power_aura_effect(image_bytes: bytes) -> bytes:
    """Post-process: stone-in-water rings from Regina — readable, spaced, not melt.

    Apply AFTER convert_to_webp. Returns WebP bytes.
    """
    import math

    import cv2
    import numpy as np

    img = Image.open(io.BytesIO(image_bytes)).convert("RGB")
    w, h = img.size
    arr = np.asarray(img, dtype=np.uint8)
    cx, cy = _power_aura_subject_center(arr)

    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32)
    dx = xs - cx
    dy = ys - cy
    dist = np.sqrt(dx * dx + dy * dy)

    core_rx, core_ry = w * 0.135, h * 0.22
    body = np.sqrt((dx / max(core_rx, 1.0)) ** 2 + (dy / max(core_ry, 1.0)) ** 2)
    amp = np.clip((body - 0.93) / 0.40, 0.0, 1.0)
    amp *= np.clip(1.22 - dist / (min(w, h) * 0.70), 0.0, 1.0)

    # Spaced rings (~4) — same look, nudged up so it reads at a glance
    wavelength = min(w, h) * 0.15
    phase = dist / max(wavelength, 1.0) * (2.0 * math.pi)
    s = np.sin(phase)
    crest = np.clip(s, 0.0, 1.0) ** 2.6 * amp
    trough = np.clip(-s, 0.0, 1.0) ** 1.5 * amp

    ux = np.divide(dx, dist, out=np.zeros_like(dx), where=dist > 1e-3)
    uy = np.divide(dy, dist, out=np.zeros_like(dy), where=dist > 1e-3)
    # Base ripple + crest push — a notch stronger than "schon gut"
    push = (s * amp * (min(w, h) * 0.012) + crest * (min(w, h) * 0.015))
    map_x = (xs + ux * push).astype(np.float32)
    map_y = (ys + uy * push).astype(np.float32)
    inside = (body < 1.0).astype(np.float32)
    map_x = map_x * (1.0 - inside) + xs * inside
    map_y = map_y * (1.0 - inside) + ys * inside
    rippled = cv2.remap(
        arr, map_x, map_y, interpolation=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT_101,
    )

    soft = cv2.GaussianBlur(rippled, (0, 0), sigmaX=5)
    t3 = (trough * 0.58).astype(np.float32)[:, :, None]
    out = rippled.astype(np.float32) * (1.0 - t3) + soft.astype(np.float32) * t3

    ridge = 1.0 + crest * 0.17 - trough * 0.09
    out = np.clip(out * ridge[:, :, None], 0, 255)

    body_keep = np.clip(1.0 - np.clip((body - 0.88) / 0.22, 0.0, 1.0), 0.0, 1.0)
    out = out * (1.0 - body_keep[:, :, None]) + arr.astype(np.float32) * body_keep[:, :, None]
    out = out.astype(np.uint8)

    buf = io.BytesIO()
    Image.fromarray(out, mode="RGB").save(buf, format="WEBP", quality=82)
    return buf.getvalue()


def convert_to_webp(image_bytes: bytes, landscape: bool = False) -> bytes:
    img = Image.open(io.BytesIO(image_bytes)).convert("RGB")
    tw = LANDSCAPE_TARGET_W if landscape else TARGET_W
    th = LANDSCAPE_TARGET_H if landscape else TARGET_H
    ratio = max(tw / img.width, th / img.height)
    nw, nh = int(img.width * ratio), int(img.height * ratio)
    img = img.resize((nw, nh), Image.LANCZOS)
    left = (nw - tw) // 2
    top = (nh - th) // 2
    img = img.crop((left, top, left + tw, top + th))
    img = img.filter(ImageFilter.UnsharpMask(radius=1, percent=80, threshold=3))

    max_kb = TARGET_KB * 1.15
    lo, hi = 10, 88
    best = None
    while lo <= hi:
        q = (lo + hi) // 2
        buf = io.BytesIO()
        img.save(buf, "WEBP", quality=q)
        data = buf.getvalue()
        if len(data) / 1024 <= max_kb:
            best = data
            lo = q + 1
        else:
            hi = q - 1
    if best is None:
        buf = io.BytesIO()
        img.save(buf, "WEBP", quality=10)
        best = buf.getvalue()
    return best

def upload_to_supabase(webp_bytes: bytes, place: dict, character_key: str, style_tag: str = "") -> str:
    place_name = _place_slug(place)
    country = place["country_code"].lower()
    filename = f"{place_name}_{country}_cast_{character_key}{style_tag}_1.webp"
    storage_path = f"cast/{filename}"
    _dedicated_upload(storage_path, webp_bytes)
    try:
        supabase.table("place_hero_images").insert({
            "place_id": place["id"],
            "storage_path": storage_path,
            "character": character_key,
            "variant": "main",
        }).execute()
    except Exception:
        pass  # storage upload succeeded; DB tracking optional
    return storage_path

