def character_subject(character_key: str, *, capital: bool = False) -> str:
    if character_key in DUO_CHARACTERS:
        return "They" if capital else "they"
    if character_key in MALE_CHARACTERS:
        return "He" if capital else "he"
    return "She" if capital else "she"


def get_duo_frame_lock(character_key: str) -> str:
    return DUO_FRAME_LOCKS.get(character_key, "")


