def get_arrival_transport_lock(character_key: str, country_code: str = "", place: dict | None = None) -> str:
    pt = ((place or {}).get("place_type") or "").lower()
    # Scenic drives / parks = road arrival. Train-only chars (werra/olga/yuki) still use their car here.
    if character_key in TRAIN_ONLY_ARRIVAL_CHARS and pt not in _NO_TRAIN_ARRIVAL_PLACE_TYPES:
        return (
            "\nARRIVAL TRANSPORT LOCK (MANDATORY): TRAIN ONLY — station platform or forecourt. "
            "NO car, NO sedan, NO BMW, NO rental vehicle in frame."
        )
    if not _character_has_road_vehicle(character_key):
        return ""
    veh = get_character_vehicle(
        character_key, country_code, place=place, activity_key="arrival",
    )
    if not veh:
        return ""
    shore = bool(place) and (
        is_shore_sand_context(place) or is_beach_place(place)
        or (place.get("terrain_type") or "") == "coastal"
    )
    _no_train = (
        "\nNO TRAIN / NO RAILWAY STATION / NO PLATFORM — this is a road arrival at a driving place."
        if pt in _NO_TRAIN_ARRIVAL_PLACE_TYPES
        else ""
    )
    if shore:
        return (
            f"\nVEHICLE (if visible): {veh}{VEHICLE_GEOMETRY_LOCK}{SHORE_VEHICLE_PLACEMENT_LOCK}{_no_train}"
        )
    return f"\nVEHICLE (MANDATORY if visible): {veh}{VEHICLE_GEOMETRY_LOCK}{_no_train}"


def get_road_identity_arrival(character_key: str, place: dict) -> str:
    terrain = place.get("terrain_type", "") or ""
    pt = (place.get("place_type") or "").lower()
    base = ROAD_IDENTITY_SPECS.get(character_key, "Character arrives by road.")
    # Scenic drive / park: force vehicle pull-off — never the train half of werra/olga/yuki specs
    if pt in _NO_TRAIN_ARRIVAL_PLACE_TYPES and character_key in TRAIN_ONLY_ARRIVAL_CHARS:
        veh = get_character_vehicle(
            character_key,
            place.get("country_code", "") or "",
            place=place,
            activity_key="arrival",
        )
        if veh:
            return (
                f"Vehicle pull-off at a scenic overlook or roadside — {veh}. "
                f"Steps out, looks at the road and landscape. "
                f"NO train, NO station, NO platform, NO railway."
            )
    if character_key == "luca":
        if terrain == "coastal":
            return (
                "Volkswagen Transporter T3 or T4 at harbour or beach. Italian plates (IT), salt-stained. "
                "Board comes out first, then him — coastal surf context only."
            )
        return (
            "Volkswagen Transporter T3 or T4 at lakeside car park, trailhead, or mountain pull-off. "
            "Italian plates (IT). He steps out in worn jeans and faded tee — NO surfboard, NO wetsuit. "
            "Optional: Moka pot or beer at the open van door. He looks at the water — hiking visitor, not surfer."
        )
    if character_key == "tammy":
        _drink = claim_tammy_energy_drink(0.15)
        if _drink:
            return (
                f"{base} Energy drink can in hand — gas station, no brand."
            )
        return f"{base} NO energy drink can this shot."
    return base


