def _quay_fishing_ok(place_type: str, terrain_type: str = "") -> bool:
    pt = (place_type or "").lower()
    pt_u = (place_type or "").upper()
    if pt_u in {"HBR", "PRT"}:
        return True
    if pt_u in {"PPLC", "PPLA", "PPLA2"} or pt in {"city", "capital", "large_town"}:
        return False
    if pt not in {"small_town", "medium_town", "village", "hamlet"} and pt_u not in {"PPL", "PPLA3", "PPLA4"}:
        return False
    return terrain_type == "coastal"


def _market_browse_ok(place_type: str) -> bool:
    """No market_browse in big cities (city / capital / PPLC / PPLA). OK in medium/small towns."""
    pt = (place_type or "").lower()
    pt_u = (place_type or "").upper()
    if pt_u in {"PPLC", "PPLA", "PPLA2"} or pt in {"city", "capital", "large_town"}:
        return False
    return True


def _yoga_mat_edge_ok(place_type: str) -> bool:
    """Terry yoga edge — not dense city / capital."""
    pt = (place_type or "").lower()
    pt_u = (place_type or "").upper()
    if pt_u in {"PPLC", "PPLA", "PPLA2"} or pt in {"city", "capital", "large_town"}:
        return False
    return True


def stairs_sprint_ok(place: dict | None) -> bool:
    """Public stairs — city/town/village or hillside/coast/lake embankment. Not desert/beach sand/scenic_drive."""
    if not place:
        return False
    pt = (place.get("place_type") or "").lower()
    pt_u = (place.get("place_type") or "").upper()
    t = (place.get("terrain_type") or "").lower()
    if pt == "scenic_drive" or t == "desert":
        return False
    if pt == "beach" or t == "beach":
        return False
    if pt in {"city", "capital", "medium_town", "small_town", "village", "large_town"}:
        return True
    if pt_u in {"PPLC", "PPLA", "PPLA2", "PPLA3", "PPLA4", "PPL"}:
        return True
    if t in {"hills", "mountain", "mountains", "coastal", "lake"}:
        return True
    return False


def lurking_ok(place: dict | None) -> bool:
    """Quiet watch in a settlement — not wilderness, beach sand, or scenic empty road."""
    if not place:
        return False
    pt = (place.get("place_type") or "").lower()
    pt_u = (place.get("place_type") or "").upper()
    if pt in {"city", "capital", "large_town", "medium_town", "small_town", "village", "hamlet"}:
        return True
    if pt_u in {"PPLC", "PPLA", "PPLA2", "PPLA3", "PPLA4", "PPL"}:
        return True
    return False


def water_jump_ok(place: dict | None) -> bool:
    """Rock/basin jump — real open water only; not city streets, not frozen Abraham Lake."""
    if not place:
        return False
    if _place_name_en(place) == "Abraham Lake":
        return False
    t = (place.get("terrain_type") or "").lower()
    if t in {"lake", "coastal"}:
        return True
    if is_beach_place(place) or is_shore_sand_context(place):
        return True
    pt = (place.get("place_type") or "").lower()
    if any(k in pt for k in ("beach", "lake", "national_park", "nature", "natural")):
        return True
    if t in {"mountain", "high_mountains", "national_park", "wilderness"}:
        name = (_place_name_en(place) or "").lower()
        return any(
            k in name
            for k in ("lake", "see", "lac", "lago", "reservoir", "cove", "bay", "fjord", "waterfall")
        ) or any(k in pt for k in ("park", "reserve", "lake"))
    return False


def water_exit_place_ok(place: dict | None) -> bool:
    """Ladder / dock / quay / pool-edge exit — only where there is a water lip to climb out onto."""
    if not place:
        return False
    if _place_name_en(place) == "Abraham Lake":
        return False
    t = (place.get("terrain_type") or "").lower()
    if t in {"lake", "coastal", "river"}:
        return True
    if is_beach_place(place) or is_shore_sand_context(place):
        return True
    name = (_place_name_en(place) or "").lower()
    pt = (place.get("place_type") or "").lower()
    keys = (
        "harbour", "harbor", "marina", "pier", "dock", "quay", "wharf",
        "pool", "lagoon", "cove", "bay", "fjord", "lake", "see", "lac", "lago",
        "beach", "strand", "plage", "playa", "praia", "river",
    )
    return any(k in name or k in pt for k in keys)


# Caldera / frozen / no casual board launch — no SUP shore push or water climb
_NO_SUP_PLACE_NAMES = frozenset({
    "Crater Lake",
    "Abraham Lake",
})


def sup_place_ok(place: dict | None) -> bool:
    """False where SUP launch is physically / contextually wrong."""
    if not place:
        return True
    return _place_name_en(place) not in _NO_SUP_PLACE_NAMES


