# Arschbombe = playful splash — wrong energy for these (Naomi + Charlotte may)
_WATER_JUMP_NO_CANNONBALL = frozenset({
    "valentina", "regina", "olga", "conrad", "isabella", "diana",
    "sigrid", "quinn", "yosra", "terry", "jonas_lara",
})
# Control / athletic clean entry only — never splash, never casual feet-first
_WATER_JUMP_HECHT_ONLY = frozenset({"valentina", "regina", "jonas_lara"})


def pick_water_jump_moment(
    variant: str | None = None, character_key: str | None = None,
) -> str:
    ck = (character_key or "").lower()
    if ck in _WATER_JUMP_HECHT_ONLY:
        if variant in ("hechtsprung", "runup") or (
            variant and _WATER_JUMP_VARIANT_ALIASES.get(variant.lower().strip()) in ("hechtsprung", "runup")
        ):
            mapped = variant if variant in WATER_JUMP_MOMENTS else _WATER_JUMP_VARIANT_ALIASES.get(
                (variant or "").lower().strip(), "hechtsprung"
            )
            return mapped if mapped in ("hechtsprung", "runup") else "hechtsprung"
        return random.choices(("runup", "hechtsprung"), weights=(0.35, 0.65), k=1)[0]
    no_cannon = ck in _WATER_JUMP_NO_CANNONBALL
    if variant in WATER_JUMP_MOMENTS:
        if variant == "cannonball" and no_cannon:
            return random.choice(("runup", "normal", "hechtsprung"))
        return variant
    if variant:
        mapped = _WATER_JUMP_VARIANT_ALIASES.get(variant.lower().strip())
        if mapped:
            if mapped == "cannonball" and no_cannon:
                return random.choice(("runup", "normal", "hechtsprung"))
            return mapped
    if no_cannon:
        return random.choices(
            ("runup", "normal", "hechtsprung"),
            weights=(0.30, 0.35, 0.35),
            k=1,
        )[0]
    return random.choices(
        ("runup", "normal", "cannonball", "hechtsprung"),
        weights=(0.28, 0.28, 0.22, 0.22),
        k=1,
    )[0]


