def is_character_home_territory(character_key: str, place: dict | None) -> bool:
    """True if place is in the character's home geo — no ticket/parking struggle there."""
    if not place or not character_key:
        return False
    cc = (place.get("country_code") or "").upper()
    if not cc:
        return False
    extra = _CHAR_HOME_EXTRA_CC.get(character_key)
    if extra and cc in extra:
        return True
    char = CAST.get(character_key)
    if not char:
        return False
    geo = char.get("geo") or {}
    region = _cast_geo_region(cc)
    if not region:
        return False
    home_w = float(geo.get(region, 0) or 0)
    other = float(geo.get("eu" if region == "us" else "us", 0) or 0)
    return home_w >= 0.5 and home_w >= other
