_CAFE_MENU_PAIR = frozenset({"menu_study", "cafe_terrace"})


_VEHICLE_CHANGE_PAIR = frozenset({"car_exit", "van_getting_dressed"})

# One sky/ridge scan beat per set — not binoculars AND fence line
_SCAN_PAIR = frozenset({"binoculars_scan", "fence_line_scan"})

# One SUP launch beat per set — shore push XOR water climb, not both
_SUP_LAUNCH_PAIR = frozenset({"sup_entry", "sup_mount"})

# Driving beats: window_down XOR cruise_through — both only on scenic_drive
_WINDOW_CRUISE_PAIR = frozenset({"window_down", "cruise_through"})


def _exclusive_pair_keep_order(acts: list[str], pair: frozenset[str]) -> list[str]:
    """If both of a pair appear, keep one at the first pair index — do not append to end."""
    present = [a for a in acts if a in pair]
    if len(present) < 2:
        return acts
    keep = random.choice(present)
    out: list[str] = []
    placed = False
    for a in acts:
        if a in pair:
            if not placed:
                out.append(keep)
                placed = True
            continue
        out.append(a)
    return out


def _mutex_window_and_cruise(
    acts: list[str],
    place_type: str = "",
    place: dict | None = None,
) -> list[str]:
    """At most one of window_down / cruise_through — both allowed only on scenic_drive."""
    if not acts:
        return acts
    if (place_type or "").lower() == "scenic_drive":
        return acts
    if not _WINDOW_CRUISE_PAIR.issubset(acts):
        return acts
    pt = (place_type or "").lower()
    # Settlements → cruise; open-road / park nature → window_down
    prefer_cruise = pt in {
        "city", "medium_town", "small_town", "village", "harbour",
    }
    if place is not None and cruise_through_ok(place=place, place_type=place_type):
        if pt not in {"national_park", "natural_park", "nature_reserve", "wilderness"}:
            prefer_cruise = True
    keep = "cruise_through" if prefer_cruise else "window_down"
    drop = next(a for a in _WINDOW_CRUISE_PAIR if a != keep)
    return [a for a in acts if a != drop]


def _cafe_menu_exclusive(acts: list[str]) -> list[str]:
    """Per set: menu XOR cafe; car_exit XOR change; binoculars XOR fence; sup_entry XOR sup_mount."""
    out = list(acts)
    out = _exclusive_pair_keep_order(out, _CAFE_MENU_PAIR)
    out = _exclusive_pair_keep_order(out, _VEHICLE_CHANGE_PAIR)
    out = _exclusive_pair_keep_order(out, _SCAN_PAIR)
    out = _exclusive_pair_keep_order(out, _SUP_LAUNCH_PAIR)
    return out


def pick_activity(
    character_key: str,
    terrain_type: str,
    place_type: str,
    n: int = 1,
    place_name: str = "",
    place: dict | None = None,
) -> list:
    def _done(seq: list[str]) -> list[str]:
        return _mutex_window_and_cruise(_cafe_menu_exclusive(list(seq)), place_type, place)

    if character_key == "regina":
        pool = [a for a in _REGINA_ALWAYS_ACTIVITIES if a not in DISABLED_ACTIVITIES]
        random.shuffle(pool)
        return _mutex_window_and_cruise(pool[: max(1, n)], place_type, place)
    if place and place_name == "Munich" and local_event_ok(place, character_key):
        return _mutex_window_and_cruise(["local_event"][: max(n, 1)], place_type, place)
    excluded = set(CHARACTER_ACTIVITY_EXCLUDE.get(character_key, []))
    if "kajak_sup" in excluded and character_key != "tammy":
        excluded.add("sup_mount")
    candidates = set()
    pt = (place_type or "").lower()
    # Scenic drives = road moments, not terrain soup (flatland waiting/cycling, etc.)
    if pt == "scenic_drive":
        candidates.update(PLACETYPE_ACTIVITIES["scenic_drive"])
    else:
        if terrain_type in TERRAIN_ACTIVITIES:
            candidates.update(TERRAIN_ACTIVITIES[terrain_type])
        for key in PLACETYPE_ACTIVITIES:
            if key in pt or pt in key:
                candidates.update(PLACETYPE_ACTIVITIES[key])
    if not candidates:
        candidates = {"van_morning_coffee", "cafe_terrace", "sunset_wine"}
    candidates -= excluded
    candidates -= DISABLED_ACTIVITIES
    # Dogs never write postcards (Goldie + all DOG_CHARACTERS)
    if character_key in DOG_CHARACTERS:
        candidates.discard("postcard_write")
    # On-duty set: no hike/run/swim/drinks — keep patrol/town beats in uniform
    if character_key == "diaz" and diaz_set_is_on_duty(place):
        candidates -= _DIAZ_OFF_DUTY_ACTIVITIES
    # Diaz + shore drinks → bikini/cover-up table shots → sexual soft_retry (Siesta Beach biergarten ×3)
    # On-duty never picks these anyway (_DIAZ_OFF_DUTY_ACTIVITIES); this blocks off-duty shore auto-pick.
    if character_key == "diaz" and place and _place_is_shoreish(place):
        candidates -= _SHORE_COVERUP_ACTIVITIES
    if pt == "scenic_drive":
        candidates -= _SCENIC_DRIVE_SWIM_BLOCK
    if character_key in _CANOE_ONLY_CHARS:
        candidates -= _SUP_WATER_ACTIVITIES
    if character_key in _SUP_ONLY_CHARS:
        candidates -= _CANOE_WATER_ACTIVITIES
    if character_key not in MALE_CHARACTERS and character_key not in _FEMALE_FISHING_OK:
        candidates.discard("quay_fishing")
        candidates.discard("river_fishing")
    if "quay_fishing" in candidates and not _quay_fishing_ok(place_type, terrain_type):
        candidates.discard("quay_fishing")
    if "market_browse" in candidates and not _market_browse_ok(place_type):
        candidates.discard("market_browse")
    if "yoga_mat_edge" in candidates and not _yoga_mat_edge_ok(place_type):
        candidates.discard("yoga_mat_edge")
    if "water_jump" in candidates and place and not water_jump_ok(place):
        candidates.discard("water_jump")
    if "freestyle_swim" in candidates and place and not water_jump_ok(place):
        candidates.discard("freestyle_swim")
    if place and not sup_place_ok(place):
        candidates -= _SUP_WATER_ACTIVITIES
    if "stairs_sprint" in candidates and place and not stairs_sprint_ok(place):
        candidates.discard("stairs_sprint")
    if "lurking" in candidates and place and not lurking_ok(place):
        candidates.discard("lurking")
    # car_exit / change-in-car need an enclosed vehicle identity; stretch ok without
    _cc = (place or {}).get("country_code", "") if place else ""
    _has_veh = bool(get_character_vehicle(character_key, _cc) or CHARACTER_VEHICLES.get(character_key))
    _pose_chg = get_character_vehicle_pose_class(character_key, "van_getting_dressed", _cc)
    # bicycle / e-scooter / road_bike: no change-beside. motorcycle+scooter = Ingrid/Thea only.
    _CHANGE_IN_CAR_BLOCKED = frozenset({"bicycle", "escooter", "road_bike"})
    if "car_exit" in candidates and not _has_veh:
        candidates.discard("car_exit")
    # van_morning_coffee = van step only — no sedan/jeep/truck/bike fake-van
    if "van_morning_coffee" in candidates:
        _pose_vmc = get_character_vehicle_pose_class(character_key, "van_morning_coffee", _cc)
        if _pose_vmc != "van":
            candidates.discard("van_morning_coffee")
    if "van_getting_dressed" in candidates and (not _has_veh or _pose_chg in _CHANGE_IN_CAR_BLOCKED):
        candidates.discard("van_getting_dressed")
    if (
        "van_getting_dressed" in candidates
        and _pose_chg in {"motorcycle", "scooter"}
        and character_key not in {"ingrid", "thea"}
    ):
        candidates.discard("van_getting_dressed")
    # change-in-car = beach/lake/nature pull-off only — never city/town/village curb
    if "van_getting_dressed" in candidates and place and _is_settlement_no_arrival(place):
        candidates.discard("van_getting_dressed")
    # Arrival XOR car_exit — road-identity places already have the arrival vehicle moment
    # (change-in-car still ok at beach/lake/nature — different beat)
    if "car_exit" in candidates and place and should_generate_road_identity(place, character_key):
        candidates.discard("car_exit")
    # Foreign ticket/parking struggle — not when she's home (Diaz in US/CA/MX, Thea in GR, …)
    if place and is_character_home_territory(character_key, place):
        candidates -= _SIGNAGE_STRUGGLE_ACTIVITIES
    if "attraction_pass" in candidates and place_name not in FAMOUS_ATTRACTION_PLACES:
        candidates.discard("attraction_pass")
    # bookstore_browse: keep in intellectual places; elsewhere soft-drop (~70%)
    if "bookstore_browse" in candidates and place and not is_bookstore_place(place):
        if random.random() < 0.70:
            candidates.discard("bookstore_browse")
    if place and local_event_ok(place, character_key):
        candidates.add("local_event")
    elif "local_event" in candidates:
        candidates.discard("local_event")
    # eating_ice_cream: settlements only — except Diaz ON DUTY (uniform snack always ok)
    if "eating_ice_cream" in candidates:
        if place and eating_ice_cream_ok(place):
            pass
        elif character_key == "diaz" and diaz_set_is_on_duty(place):
            pass
        else:
            candidates.discard("eating_ice_cream")
    # Americas: ferry_rail only where DB has real ferry (ferry_minutes > 0)
    if "ferry_rail" in candidates and place and not ferry_rail_ok(place):
        candidates.discard("ferry_rail")
    if place and is_shore_sand_context(place):
        candidates -= _SHORE_EXCLUDED_ACTIVITIES
        if not candidates:
            candidates = set(_SHORE_ACTIVITY_FALLBACK) - excluded
    if place and is_nature_place(place):
        candidates = {a for a in candidates if nature_activity_ok(place, a)}
        # On-duty town/patrol beats still ok in desert border towns (Bisbee etc.)
        if character_key == "diaz" and diaz_set_is_on_duty(place):
            candidates.add("eating_ice_cream")  # always — donut/cone in uniform
            candidates.update({
                "diner_booth", "radio_check", "draw_weapon",
                "binoculars_scan", "fence_line_scan",  # XOR later — never both in one set
            })
    if place and is_heritage_site(place):
        candidates -= _HERITAGE_BLOCKED_ACTIVITIES
    if place:
        candidates = {a for a in candidates if campfire_activity_ok(place, a)}
    if place and "rope_coil" in candidates and not rope_coil_ok(place):
        candidates.discard("rope_coil")
    if place:
        candidates = {a for a in candidates if ocean_beach_activity_ok(place, a)}
    # binoculars_scan: beach/shore only for werra — others never on sand
    if (
        "binoculars_scan" in candidates
        and character_key != "werra"
        and (
            (place and is_shore_sand_context(place))
            or (place_type or "").lower() == "beach"
        )
    ):
        candidates.discard("binoculars_scan")
    # Ortschaften: Fernglas only for Diaz + investigator duos (not tourist scan in town)
    if (
        "binoculars_scan" in candidates
        and place
        and _is_settlement_place(place)
        and character_key not in {"diaz", "jack_mae", "jonas_lara"}
    ):
        candidates.discard("binoculars_scan")
    # bouldern = real outdoor rock — never city park / Plano playground boulder
    if "bouldern" in candidates and place and (
        is_urban_place(place) or _is_settlement_place(place)
    ):
        candidates.discard("bouldern")
    if not _road_moment_ok(place_type):
        candidates -= _SCENIC_ROAD_MOMENTS
    if "cruise_through" in candidates:
        if not cruise_through_ok(place=place, place_type=place_type):
            candidates.discard("cruise_through")
        elif not _road_moment_allowed(character_key, "cruise_through"):
            candidates.discard("cruise_through")
    for _rm in list((_SCENIC_ROAD_MOMENTS) & candidates):
        if not _road_moment_allowed(character_key, _rm):
            candidates.discard(_rm)
    # photo_lab only for yosra and tasha — analogue camera chars
    if character_key not in {"yosra", "tasha"}:
        candidates.discard("photo_lab")
    if character_key not in _CIGARETTE_ROLL_CHARS:
        candidates.discard("cigarette_roll")
    # US cast doesn't cycle (cars/trucks/Jeeps). Zara is EU-home + bicycle identity — keep allowed.
    if CHAR_HOME_CONTINENT.get(character_key) == "us":
        candidates.discard("cycling_road")
    # Jonas & Lara = Volvo investigators — never road-cycling holiday
    if character_key == "jonas_lara":
        candidates.discard("cycling_road")
    # Djordje = W124 diesel — never bicycle
    if character_key == "djordje":
        candidates.discard("cycling_road")
    # Investigator duos — no roadside yoga stretch (solo travel beat)
    if character_key in DUO_CHARACTERS:
        candidates.discard("stretch")
    # stretch — keep rare; was competing equally in every town pool
    if "stretch" in candidates and random.random() < 0.72:
        candidates.discard("stretch")
    # closed_door — turn down; town pools over-pick the hours-sign beat
    if "closed_door" in candidates and random.random() < 0.60:
        candidates.discard("closed_door")
    # Zara — reduce beach bikini acts (cover-up on remaining shore walks)
    if character_key == "zara":
        for _za in list(_ZARA_BEACH_SOFT_DROP & candidates):
            if random.random() < 0.70:
                candidates.discard(_za)
    if "fueling_car" in candidates and not fueling_car_ok(character_key, place):
        candidates.discard("fueling_car")
    if "hood_check" in candidates and not hood_check_ok(character_key, place):
        candidates.discard("hood_check")
    for _act, _owners in _CHAR_ACTIVITY_OWNERS.items():
        if character_key not in _owners:
            candidates.discard(_act)
    if "menu_study" in candidates and "cafe_terrace" in candidates:
        candidates.discard(random.choice(("menu_study", "cafe_terrace")))
    # Diaz ON DUTY set: ice cream / donut snack always eligible (any frontera place)
    if character_key == "diaz" and diaz_set_is_on_duty(place):
        candidates.add("eating_ice_cream")
        # Auto fueling keeps breaking (nozzle on heck / double hose) — skip unless --activity-key
        candidates.discard("fueling_car")
    candidates = list(candidates)
    if not candidates:
        return []
    # On-duty set: before athletic soft-pins (trail_running/bouldern) steal the set
    if character_key == "diaz" and diaz_set_is_on_duty(place):
        preferred = [a for a in _DIAZ_ON_DUTY_PREFERRED_ACTIVITIES if a in candidates]
        if preferred:
            random.shuffle(preferred)
            # Soft bias: radio / snack / sky-scan often lead the set
            for _bias, _p in (
                ("eating_ice_cream", 0.30),  # eis/donut halten+mampfen
                ("radio_check", 0.26),
                ("binoculars_scan", 0.20),
            ):
                if _bias in preferred and random.random() < _p:
                    preferred = [_bias] + [a for a in preferred if a != _bias]
                    break
            rest = [a for a in candidates if a not in preferred]
            random.shuffle(rest)
            return _done(preferred + rest)[:n]
    # Soft boost: mapped local_event is rare by design — ~28% put it first when eligible
    if "local_event" in candidates and random.random() < 0.28:
        rest = [a for a in candidates if a != "local_event"]
        random.shuffle(rest)
        return _done(["local_event"] + rest)[:n]
    # bookstore_browse — soft pin in literary / university towns (Port Angeles, Oxford, …)
    if (
        "bookstore_browse" in candidates
        and place
        and is_bookstore_place(place)
        and random.random() < 0.22
    ):
        rest = [a for a in candidates if a != "bookstore_browse"]
        random.shuffle(rest)
        return _done(["bookstore_browse"] + rest)[:n]
    # Amber signature — coyote companion should show often outdoors
    if character_key == "amber" and "coyote_glance" in candidates and random.random() < 0.32:
        rest = [a for a in candidates if a != "coyote_glance"]
        random.shuffle(rest)
        return _done(["coyote_glance"] + rest)[:n]
    # lurking — soft pin in settlements for watchers / road observers
    if "lurking" in candidates and place and lurking_ok(place):
        _lp = {
            "miles": 0.36, "dale": 0.30, "tyler": 0.22,
            "werra": 0.24, "quinn": 0.22, "diaz": 0.22, "diana": 0.24,
            "jade": 0.20, "amber": 0.18, "katja": 0.20, "jelena": 0.18,
            "jonas_lara": 0.26, "jack_mae": 0.26, "camille": 0.18, "terry": 0.18,
            "kelek": 0.18, "lyra": 0.16, "yuki": 0.16, "charlotte": 0.16,
            "ingrid": 0.16, "yosra": 0.20, "tammy": 0.16,
        }.get(character_key, 0.0)
        if _lp and random.random() < _lp:
            rest = [a for a in candidates if a != "lurking"]
            random.shuffle(rest)
            return _done(["lurking"] + rest)[:n]
    # Maya — soft boost hood_check only (body-juice land chore; laundromat already frequent)
    if character_key == "maya" and "hood_check" in candidates and random.random() < 0.24:
        rest = [a for a in candidates if a != "hood_check"]
        random.shuffle(rest)
        return _done(["hood_check"] + rest)[:n]
    # Isabella — soft boost sunset_wine (Lansing seated gold)
    if character_key == "isabella" and "sunset_wine" in candidates and random.random() < 0.26:
        rest = [a for a in candidates if a != "sunset_wine"]
        random.shuffle(rest)
        return _done(["sunset_wine"] + rest)[:n]
    # fueling_car — cinematic road-movie beat; light global boost (pump-wait gold)
    if "fueling_car" in candidates and place:
        _fcc = (place.get("country_code") or "").upper()
        if _fcc in AMERICAS_CODES and random.random() < 0.28:
            rest = [a for a in candidates if a != "fueling_car"]
            random.shuffle(rest)
            return _done(["fueling_car"] + rest)[:n]
        if _fcc not in AMERICAS_CODES:
            if random.random() < 0.12:
                rest = [a for a in candidates if a != "fueling_car"]
                random.shuffle(rest)
                return _done(["fueling_car"] + rest)[:n]
            if random.random() < 0.40:
                candidates = [a for a in candidates if a != "fueling_car"]
                if not candidates:
                    return []
    # bouldern — soft boost; stronger in desert / rock country; juicy boulder cast boosted
    if "bouldern" in candidates and place:
        _bt = (place.get("terrain_type") or "").lower()
        _bn = (place.get("name_en") or "").lower()
        _bp = 0.18
        if _bt == "desert" or "joshua" in _bn or "moab" in _bn or "boulder" in _bn:
            _bp = 0.32
        if character_key in _JUICY_BOULDER_CHARS:
            _bp = 0.40
            if _bt == "desert" or "joshua" in _bn or "moab" in _bn or "boulder" in _bn or "hueco" in _bn:
                _bp = 0.50
        if random.random() < _bp:
            rest = [a for a in candidates if a != "bouldern"]
            random.shuffle(rest)
            return _done(["bouldern"] + rest)[:n]
    # trail_running — nature / NP / mountain soft boost for outdoor cast
    if "trail_running" in candidates and place and character_key in {
        "maya", "jade", "kay", "alessandra", "rosa", "amber", "tasha", "diaz",
    }:
        _tt = (place.get("terrain_type") or "").lower()
        _pt = (place.get("place_type") or "").lower()
        if (
            _tt in {"mountain", "mountains", "high_mountains", "hills", "desert", "national_park", "wilderness", "lake"}
            or _pt in {"national_park", "nature_reserve", "natural_park"}
            or "yosemite" in (place.get("name_en") or "").lower()
        ):
            if random.random() < 0.26:
                rest = [a for a in candidates if a != "trail_running"]
                random.shuffle(rest)
                return _done(["trail_running"] + rest)[:n]
    # freestyle_swim — open-water crawl; juicy swim cast stronger soft-pin
    if "freestyle_swim" in candidates and place and character_key in _CHAR_ACTIVITY_OWNERS.get("freestyle_swim", ()):
        _tt = (place.get("terrain_type") or "").lower()
        if _tt in {"lake", "coastal"} or water_jump_ok(place):
            _sw_p = 0.42 if character_key in _JUICY_SWIM_CHARS else 0.28
            if random.random() < _sw_p:
                rest = [a for a in candidates if a != "freestyle_swim"]
                random.shuffle(rest)
                return _done(["freestyle_swim"] + rest)[:n]
    # surfing — ocean wave mid-ride; juicy surf cast stronger soft-pin
    if "surfing" in candidates and place and character_key in _CHAR_ACTIVITY_OWNERS.get("surfing", ()):
        if ocean_beach_activity_ok(place, "surfing"):
            _sf_p = 0.45 if character_key in _JUICY_SURF_CHARS else 0.30
            if random.random() < _sf_p:
                rest = [a for a in candidates if a != "surfing"]
                random.shuffle(rest)
                return _done(["surfing"] + rest)[:n]
    # stairs_sprint — open cast; Jelena soft-pinned hard (signature energy); Stacy lighter energy pin
    if character_key == "jelena" and "stairs_sprint" in candidates and random.random() < 0.42:
        rest = [a for a in candidates if a != "stairs_sprint"]
        random.shuffle(rest)
        return _done(["stairs_sprint"] + rest)[:n]
    if character_key == "stacy" and "stairs_sprint" in candidates and random.random() < 0.28:
        rest = [a for a in candidates if a != "stairs_sprint"]
        random.shuffle(rest)
        return _done(["stairs_sprint"] + rest)[:n]
    # eating_ice_cream — town gelato / comic-relief / Diaz uniform-snack soft pin
    # (skipped when --diaz-on-duty already returned preferred pool above)
    if "eating_ice_cream" in candidates and character_key in {
        "djordje", "stacy", "luca", "thea", "jelena", "dale", "diaz",
    } and not (character_key == "diaz" and diaz_set_is_on_duty(place)):
        _ice_p = 0.38 if character_key == "diaz" and place and is_diaz_border_place(place) else (
            0.12 if character_key == "diaz" else 0.34
        )
        if random.random() < _ice_p:
            rest = [a for a in candidates if a != "eating_ice_cream"]
            random.shuffle(rest)
            return _done(["eating_ice_cream"] + rest)[:n]
    # Settlements (city → small_town like Bar): no road-identity — rare soft-pin car_exit / stretch
    # (arrival XOR car_exit: towns get car_exit instead of arrival, but not often)
    if place and _is_settlement_no_arrival(place):
        if "car_exit" in candidates and random.random() < 0.10:
            rest = [a for a in candidates if a != "car_exit"]
            random.shuffle(rest)
            return _done(["car_exit"] + rest)[:n]
        if "stretch" in candidates and random.random() < 0.04:
            rest = [a for a in candidates if a != "stretch"]
            random.shuffle(rest)
            return _done(["stretch"] + rest)[:n]
    # Beach / lake / nature pull-offs — rare change-in-car (never settlements)
    elif place and "van_getting_dressed" in candidates and random.random() < 0.08:
        rest = [a for a in candidates if a != "van_getting_dressed"]
        random.shuffle(rest)
        return _done(["van_getting_dressed"] + rest)[:n]
    if character_key == "jelena" and "stray_dogs" in candidates and random.random() < 0.28:
        rest = [a for a in candidates if a != "stray_dogs"]
        random.shuffle(rest)
        return _done(["stray_dogs"] + rest)[:n]
    if character_key == "jelena" and "hausmeister_chat" in candidates and random.random() < 0.24:
        rest = [a for a in candidates if a != "hausmeister_chat"]
        random.shuffle(rest)
        return _done(["hausmeister_chat"] + rest)[:n]
    if character_key == "jelena" and "local_chat" in candidates and random.random() < 0.26:
        rest = [a for a in candidates if a != "local_chat"]
        random.shuffle(rest)
        return _done(["local_chat"] + rest)[:n]
    if character_key == "werra" and "local_chat" in candidates and random.random() < 0.24:
        rest = [a for a in candidates if a != "local_chat"]
        random.shuffle(rest)
        return _done(["local_chat"] + rest)[:n]
    if character_key == "jonas_lara" and "local_chat" in candidates and random.random() < 0.22:
        rest = [a for a in candidates if a != "local_chat"]
        random.shuffle(rest)
        return _done(["local_chat"] + rest)[:n]
    if character_key == "jelena" and "going_for_a_run" in candidates and random.random() < 0.18:
        rest = [a for a in candidates if a != "going_for_a_run"]
        random.shuffle(rest)
        return _done(["going_for_a_run"] + rest)[:n]
    # scenic_drive identity: always lead with window_down + cruise_through (when eligible)
    if pt == "scenic_drive":
        ordered = []
        for _sd_key in ("window_down", "cruise_through"):
            if _sd_key in candidates:
                ordered.append(_sd_key)
        rest = [a for a in candidates if a not in ordered]
        random.shuffle(rest)
        return _done(ordered + rest)[:n]
    random.shuffle(candidates)
    return _done(candidates[:n])


_JELENA_ASS_LOCK = (
    "JELENA PHYSIQUE (mandatory): soft hourglass — narrow waist, natural full chest/hips, "
    "full round glutes (form over size, not cartoon). Body under clothes — never flat/pencil/runner-thin."
)


def get_character_activity_profile(
    character_key: str,
    activity_key: str,
    activity_variant: str | None = None,
    tammy_energy_drink: bool = False,
    place: dict | None = None,
) -> str:
    """Body/markers for water/outdoor activities; outfit via outfit_override in build_activity_prompt."""
    if activity_key in _RUN_KIT_ACTIVITIES:
        run_note = CHARACTER_RUN_ACTIVITY_PROFILE.get(character_key)
        if run_note:
            return run_note
    if activity_key not in _PROFILE_ACTIVITIES:
        return ""
    parts = []
    anchor = CHARACTER_BODY_ANCHORS.get(character_key)
    if anchor:
        parts.append(f"CHARACTER BODY & MARKERS (MANDATORY): {anchor}")
    for _lock in (
        get_character_nails_lock(character_key),
        get_character_marks_lock(character_key),
        get_character_piercings_lock(character_key),
    ):
        if _lock:
            parts.append(_lock)
    _jade_pose = get_jade_pose_lock(character_key, activity_key)
    if _jade_pose:
        parts.append(_jade_pose)
    if activity_key in _SWIM_OUTFIT_ACTIVITIES:
        water = get_character_water_outfit(character_key, place, activity_key=activity_key)
        if water:
            parts.append(f"SWIM/BEACH (MANDATORY): {water}")
    if activity_key == "surf_paddle" and character_key == "kay":
        parts.append(
            "SURF OUTFIT (MANDATORY — KAY): black 3mm wetsuit half-unzipped or peeled to waist, "
            "or black fitted tank — white ORCA silhouette on chest only. "
            "FORBIDDEN: three-wave lines (Maya). Longboard nearby ok. Barefoot on sand/path."
        )
    elif activity_key == "surf_paddle" and character_key == "sofia":
        parts.append("SURF OUTFIT (MANDATORY): bikini or rashguard, board under arm, barefoot on approach.")
    elif activity_key == "surfing" and character_key == "kay":
        parts.append(
            "SURFING OUTFIT (MANDATORY — KAY): black bikini or black 3mm wetsuit (half-zip/peeled ok). "
            "CHEST MARK: small white ORCA silhouette only — Sedna mark. "
            "FORBIDDEN: three horizontal wave lines / Maya training emblem / Salt Life text logo. "
            "If any chest mark is not a clear white orca shape, the shot has failed. "
            "Barefoot ON the board. Mid-ride Pacific/CA energy — decades of salt, not teen Sporty Spice."
        )
    elif activity_key == "surfing" and character_key == "maya":
        parts.append(
            "SURFING OUTFIT (MANDATORY — MAYA): sport bikini or competition swim top — "
            "three-wave-line chest emblem OK (her mark). NEVER white orca (that is Kay). "
            "Barefoot ON the board. Mid-ride."
        )
    elif activity_key == "surfing" and character_key == "sofia":
        parts.append(
            "SURFING OUTFIT (MANDATORY): bikini or rashguard — barefoot ON the board mid-ride. "
            "Silver crescent necklace if collarbone readable. Not carrying the board. No orca, no three-wave."
        )
    elif activity_key == "surfing" and character_key == "luca":
        parts.append(
            "SURFING OUTFIT (MANDATORY): worn board shorts, bare chest — barefoot ON the board mid-ride. "
            "NOT jeans, NOT model-handsome. Weirdly attractive van-bum energy only."
        )
    elif activity_key == "surfing" and character_key in {"tasha", "ana"}:
        parts.append(
            "SURFING OUTFIT (MANDATORY): athletic bikini — barefoot ON the board mid-ride. "
            "No orca silhouette, no three-wave emblem (Kay/Maya marks only)."
        )
    if character_key == "regina":
        _regina_locks = get_regina_prompt_locks(character_key, activity_key)
        if _regina_locks:
            parts.append(_regina_locks)
    # sup_mount wet/muscle: ACTIVITY_SPECS + get_sup_mount_variant_blocks (once each) — no third copy
    _tammy_prop = get_tammy_mouth_prop_lock(character_key, energy_drink=tammy_energy_drink)
    if _tammy_prop and activity_key not in {"going_for_a_run", "hiking_back", "snowshoe_hike", "desert_walk", "cycling_road", "morning_run_urban"}:
        parts.append(_tammy_prop)
    return "\n".join(parts)


_SIGNAGE_ACTIVITIES = frozenset({
    "closed_door", "ticket_machine", "parking_puzzle", "waiting",
    "kiosk_stop", "cash_pay", "menu_study", "attraction_pass", "newspaper_cafe",
    "market_browse", "fueling_car",
})

_US_BILINGUAL_REGION_KEYS = frozenset({
    "texas", "florida", "arizona", "new mexico", "louisiana", "mississippi", "alabama",
    "georgia", "south carolina", "north carolina", "arkansas", "oklahoma", "tennessee",
    "nevada", "california", "colorado", "san antonio", "miami", "el paso", "houston",
    "phoenix", "tucson", "albuquerque", "new orleans", "austin", "dallas",
})


def _us_bilingual_signage_ok(place: dict) -> bool:
    hay = f"{place.get('state_name', '')} {place.get('name_en', '')}".lower()
    return any(k in hay for k in _US_BILINGUAL_REGION_KEYS)


_FUELING_BLOCKED_POSE = frozenset({
    "motorcycle", "scooter", "bicycle", "escooter", "road_bike",
})


def fueling_car_ok(character_key: str, place: dict | None = None) -> bool:
    """Car/truck/van/jeep at a pump — not two-wheel, not chauffeured, not driver shells."""
    if character_key in _CHAUFFEURED_CHARS or character_key in {"driver_pov", "driver_van", "goldie"}:
        return False
    cc = (place or {}).get("country_code", "") if place else ""
    if not get_character_vehicle(character_key, cc):
        return False
    pose = get_character_vehicle_pose_class(character_key, "fueling_car", cc)
    if pose in _FUELING_BLOCKED_POSE:
        return False
    return True


def hood_check_ok(character_key: str, place: dict | None = None) -> bool:
    """Open-hood engine check from behind — female solo car/van/jeep only."""
    if character_key in MALE_CHARACTERS or character_key in DUO_CHARACTERS:
        return False
    if character_key in _CHAUFFEURED_CHARS or character_key in {"driver_pov", "driver_van", "goldie"}:
        return False
    if character_key in DISABLED_CHARACTERS:
        return False
    cc = (place or {}).get("country_code", "") if place else ""
    if not get_character_vehicle(character_key, cc):
        return False
    pose = get_character_vehicle_pose_class(character_key, "hood_check", cc)
    return pose not in _FUELING_BLOCKED_POSE


