def _is_settlement_place(place: dict) -> bool:
    _pt = (place.get("place_type") or "").lower()
    _ptu = (place.get("place_type") or "").upper()
    return (
        _pt in {
            "village", "hamlet", "small_town", "medium_town", "city", "capital",
            "isolated_dwelling",
        }
        or _ptu in {"PPL", "PPLA", "PPLA2", "PPLA3", "PPLA4", "PPLC", "PPLX"}
    )


def eating_ice_cream_ok(place: dict | None) -> bool:
    """Ice cream only in Ortschaften — any size town/village/city, not pure nature/beach parks."""
    if not place:
        return False
    if _is_settlement_place(place) or is_urban_place(place):
        return True
    pt = (place.get("place_type") or "").lower()
    # harbour / resort / large_town count as settlements for gelato street energy
    return pt in {"harbour", "resort", "large_town"}


def place_has_ferry(place: dict | None) -> bool:
    """True only when DB marks real ferry access (ferry_minutes > 0)."""
    if not place:
        return False
    fm = place.get("ferry_minutes")
    try:
        return fm is not None and float(fm) > 0
    except (TypeError, ValueError):
        return False


def ferry_rail_ok(place: dict | None) -> bool:
    """ferry_rail only where DB marks real ferry (ferry_minutes > 0) — EU and Americas."""
    if not place:
        return False
    return place_has_ferry(place)


def get_duo_background_infra_note(
    character_key: str,
    place: dict,
    *,
    always: bool = False,
) -> str:
    """Subtle wind/data/edge-of-town infra for jack_mae / jonas_lara / werra.
    always=True (farshot / hiking_back / dayhike): always inject one far mark.
    Settlement: mark stays BEYOND the buildings, never in the street fabric.
    Other main: ~45% on open country; rare on settlements."""
    if character_key not in {"jonas_lara", "jack_mae", "werra"}:
        return ""
    _settlement = _is_settlement_place(place)
    if not always:
        if _settlement:
            if random.random() >= 0.12:
                return (
                    "\nBACKGROUND INFRA: Settlement / town street — no turbines/data campuses/masts "
                    "among the buildings. Ordinary street fabric only."
                )
            # rare: horizon beyond town
        elif random.random() >= 0.45:
            return ""
    if character_key in {"jonas_lara", "werra"}:
        _infra = random.choice((
            "distant wind turbines on a far ridge — small soft silhouettes, still readable",
            "a pale low data-centre / server campus behind trees or fence — anonymous boxes, no logos, no glow",
            "a radio / weather / telecom mast or white radome on a distant hill — silhouette readable",
            # soft "change at the edge" — no slogans, no people as props
            "a half-finished housing estate on the far edge of town — cranes or bare roofs, almost no people visible",
            "a new logistics / warehouse hall at the horizon next to older fields — anonymous grey box, no brand text",
            "a shuttered roadside inn / empty Gasthof silhouette at the place edge — soft, far, secondary",
        ))
        _where = (
            "Beyond the village/town buildings, on a far ridge or open horizon — NOT in the street among houses — "
            if _settlement
            else "Far mid-ground / horizon MUST show — "
        )
        _who = (
            "Werra + place/G-Class stay primary."
            if character_key == "werra"
            else "Pair + place/Volvo stay primary."
        )
        return (
            f"\nBACKGROUND INFRA (MANDATORY, subtle): {_where}{_infra}. "
            f"Present in frame, soft and secondary — not the hero subject. "
            f"No protest, no labels, no sci-fi glow. {_who}"
        )
    _infra = random.choice((
        "a few prairie wind turbines on the far horizon — small hazy silhouettes, still readable",
        "a low anonymous US hyperscale data campus outside town — beige warehouse boxes, no logos, no glow",
        "a distant AM/FM radio tower or microwave relay mast — thin silhouette, readable",
        "a far NEXRAD-style weather dome on a rise — small pale dome, readable",
        "a half-built subdivision on the far edge of town — framing, empty lots, almost no people",
        "a new warehouse / logistics shed on the prairie edge — anonymous, no brand text",
    ))
    _where = (
        "Beyond the town buildings, on a far open horizon — NOT on Main Street among shops — "
        if _settlement
        else "Far horizon MUST show — "
    )
    return (
        f"\nBACKGROUND INFRA (MANDATORY, subtle): {_where}{_infra}. "
        "US West vernacular. Present in frame, soft and secondary — not the hero subject. "
        "No protest, no labels, no sci-fi. Pair + road/pickup stay primary."
    )


