def _is_city_place(place: dict | None) -> bool:
    if not place:
        return False
    pt_u = (place.get("place_type") or "").upper()
    pt_l = (place.get("place_type") or "").lower()
    if pt_u in ("PPLC", "PPLA", "PPL", "PPLA2"):
        return True
    return pt_l in ("city", "capital", "large_town", "medium_town")


def _night_place_ok(place: dict | None) -> bool:
    """Cities / named night magnets only — never nature or daytime beach."""
    if not place:
        return False
    if is_nature_place(place) and not is_heritage_site(place):
        return False
    if is_beach_place(place) and not _is_city_place(place):
        return False
    name = place.get("name_en") or ""
    if name in _NIGHT_OK_PLACE_NAMES:
        return True
    score = place.get("attractiveness_score") or 0
    return _is_city_place(place) and score >= 90


def _is_dark_rain_place(place: dict | None) -> bool:
    """Regen / Herbst / düstere Städte → eclipse/noir bucket."""
    if not place or not _is_city_place(place):
        return False
    name = place.get("name_en") or ""
    if name in _DARK_RAIN_PLACE_NAMES or name in _US_DARK_RAIN_PLACES:
        return True
    cc = (place.get("country_code") or "").upper()
    return cc in _RAIN_DARK_CC


def _is_modern_metro_place(place: dict | None) -> bool:
    if not place or not _is_city_place(place):
        return False
    name = place.get("name_en") or ""
    if name in _MODERN_METRO_NAMES:
        return True
    cc = (place.get("country_code") or "").upper()
    return cc in _NORDIC_PREM_CC and _is_city_place(place)


def _is_med_balkan_anatolia_place(place: dict | None) -> bool:
    if not place:
        return False
    cc = (place.get("country_code") or "").upper()
    terrain = (place.get("terrain_type") or "").lower()
    if cc in _BALKAN_PREM_CC or cc in _ANATOLIA_PREM_CC or cc in _MED_PREM_CC:
        return True
    if cc == "FR" and terrain == "coastal":
        return True
    return False


def _is_mitteleuropa_or_alps_place(place: dict | None) -> bool:
    """Plain roadtrip register — Alpen / Mitteleuropa (not dark metros)."""
    if not place:
        return False
    cc = (place.get("country_code") or "").upper()
    terrain = (place.get("terrain_type") or "").lower()
    if cc in _ALPS_PREM_CC:
        return True
    if cc in _MITTELEUROPA_PREM_CC:
        return True
    if terrain in ("mountain", "mountains", "high_mountains") and cc in {"FR", "IT", "DE", "SI"}:
        return True
    return False


def _noir_fits_100(place: dict | None) -> bool:
    """Noir only when hard rain/crime register is unmistakable."""
    if not place:
        return False
    name = place.get("name_en") or ""
    return name in _NOIR_PERFECT_PLACES


def _prefer_eclipse_over_noir(layer: str | None, place: dict | None) -> str | None:
    """Almost always prefer eclipse; keep noir only on perfect-fit places."""
    if layer != "noir":
        return layer
    if _noir_fits_100(place):
        return "noir"
    return "eclipse"


# Sentinel: geo matrix has no opinion → allow CHARACTER_PREMIUM_PREFER
_GEO_NO_OPINION = object()


def _eu_geo_premium(place: dict):
    """Geo matrix for EU. Returns layer, None (plain), or _GEO_NO_OPINION."""
    if is_heritage_site(place):
        return "continental"
    if _is_dark_rain_place(place):
        return "noir" if _noir_fits_100(place) else "eclipse"
    if _is_modern_metro_place(place) and not _is_med_balkan_anatolia_place(place):
        return "viper"
    cc = (place.get("country_code") or "").upper()
    if cc in _NORDIC_PREM_CC:
        return "viper"
    if _is_med_balkan_anatolia_place(place):
        return "continental"
    if _is_mitteleuropa_or_alps_place(place):
        return None  # plain
    return _GEO_NO_OPINION


def _us_geo_premium(place: dict):
    """Geo matrix for US/CA/MX-Americas. Returns layer, None, or _GEO_NO_OPINION."""
    name = place.get("name_en") or ""
    terrain = (place.get("terrain_type") or "").lower()
    pt_l = (place.get("place_type") or "").lower()
    # True nature parks / wilderness → plain (not desert towns)
    if pt_l in _NATURE_PLACE_TYPES or pt_l in {"national_park", "wilderness", "nature_reserve"}:
        return None
    if _is_dark_rain_place(place) or name in _US_DARK_RAIN_PLACES:
        return "noir" if _noir_fits_100(place) else "eclipse"
    if name in _US_SIDEWINDER_METRO:
        return "sidewinder"
    if terrain in _US_SIDEWINDER_CC_COAST_DESERT:
        return "sidewinder"
    if is_heritage_site(place):
        return "sidewinder"
    if _is_city_place(place):
        return "sidewinder"
    # small-town / generic roadtrip → plain
    return None


def _day_prem_fallback(
    place: dict,
    character_key: str,
    is_us: bool,
) -> str | None:
    """Replace blocked nightlife with daylight geo register (or char day pref)."""
    if character_key == "maya":
        return None
    if is_us:
        if character_key == "isabella" and _is_city_place(place):
            return "prestige"
        geo = _us_geo_premium(place)
        if geo is not _GEO_NO_OPINION:
            return _prefer_eclipse_over_noir(geo, place) if geo else None
        return "sidewinder"
    if is_nature_place(place) and not is_heritage_site(place):
        return None
    geo = _eu_geo_premium(place)
    if geo is not _GEO_NO_OPINION:
        return _prefer_eclipse_over_noir(geo, place) if geo else None
    pref = CHARACTER_PREMIUM_PREFER.get(character_key) or []
    day = [x for x in pref if x and x not in ("nightlife", "noir", "eclipse")]
    if day:
        return random.choice(day)
    if _is_city_place(place) or (place.get("terrain_type") or "") == "coastal":
        return "continental"
    return None


def _apply_night_noir_gate(
    layer: str | None,
    place: dict,
    character_key: str,
    is_us: bool,
) -> str | None:
    """Nightlife rare via whitelist. Noir almost never — eclipse preferred."""
    if layer == "nightlife":
        if (
            character_key in _NIGHTLIFE_OK_CHARS
            and _night_place_ok(place)
            and random.random() < _NIGHT_LAYER_KEEP_P
        ):
            return "nightlife"
        return _day_prem_fallback(place, character_key, is_us)
    if layer == "noir":
        # Hard noir only on perfect-fit places; else eclipse (or day fallback)
        if _noir_fits_100(place):
            return "noir"
        if _is_dark_rain_place(place):
            return "eclipse"
        keep_p = 0.55 if character_key == "diana" else _NIGHT_LAYER_KEEP_P
        if (
            character_key in _NOIR_OK_CHARS
            and _night_place_ok(place)
            and random.random() < keep_p
        ):
            # still flip to eclipse unless perfect — diana gets eclipse on non-perfect
            return "eclipse"
        return _day_prem_fallback(place, character_key, is_us)
    return layer


def _finalize_premium_layer(
    layer: str | None,
    place: dict,
    is_us: bool,
    character_key: str | None = None,
) -> str | None:
    """US: keep eclipse/noir/nightlife; Isabella city prestige; else sidewinder.
    EU nature: none (heritage ok)."""
    if not layer:
        return None
    char = (character_key or "").lower()
    if is_us:
        if layer in ("nightlife", "noir", "eclipse"):
            return layer
        if char == "isabella" and layer == "prestige" and _is_city_place(place):
            return "prestige"
        if layer == "sidewinder":
            return "sidewinder"
        # continental/viper etc. don't map to US — sidewinder
        return "sidewinder"
    if is_nature_place(place) and not is_heritage_site(place):
        return None
    return layer


def _isabella_city_premium() -> str:
    """~80% prestige in US cities — nightlife only if later night-gate opens (rare)."""
    return random.choice([
        "prestige", "prestige", "prestige", "prestige",
        "prestige", "prestige", "prestige", "prestige",
        "prestige", "nightlife",
    ])


# Soft eclipse flavor — investigator duos often-ish; miles rarer. Does not override
# place LOCK, nature plain, dark-bucket eclipse/noir, or nightlife.
_ECLIPSE_SOFT_P = {
    "jonas_lara": 0.42,
    "jack_mae":   0.42,
    "miles":      0.18,
}


def _maybe_soft_eclipse(
    chosen: str | None,
    character_key: str,
    place: dict,
) -> str | None:
    """Sometimes upgrade plain / road day layers to eclipse for selected chars."""
    p = _ECLIPSE_SOFT_P.get((character_key or "").lower())
    if p is None:
        return chosen
    if chosen in ("eclipse", "noir", "nightlife", "prestige"):
        return chosen
    # Only from plain / continental / sidewinder day registers
    if chosen not in (None, "continental", "sidewinder"):
        return chosen
    # Skip true nature parks — not desert towns (terrain=desert still settles)
    pt_l = (place.get("place_type") or "").lower()
    if pt_l in _NATURE_PLACE_TYPES or pt_l in {"national_park", "wilderness", "nature_reserve"}:
        return chosen
    if random.random() < p:
        return "eclipse"
    return chosen


def pick_premium_layer(place: dict, character_key: str, void_energy: float = 0) -> str | None:
    """Auto-select premium layer based on place, character, and void_energy score."""
    country = place.get("country_code", "")
    terrain = place.get("terrain_type", "")
    score = place.get("attractiveness_score", 0)
    place_name = place.get("name_en", "")
    is_us = country in AMERICAS_CODES
    char = (character_key or "").lower()

    # Threshold check
    if score < 85 and void_energy < 7:
        return None
    # Driver chars and probation chars don't get premium layer
    if char in ["driver_pov", "driver_van"] or char in PROBATION_CHARACTERS:
        return None
    if char in DISABLED_CHARACTERS:
        return None

    # EU nature: no auto premium — except archaeology/heritage → continental
    # US desert towns are not "nature" for this gate (handled in _us_geo_premium)
    if not is_us and is_nature_place(place) and not is_heritage_site(place):
        return None

    chosen = None

    # 1. Place hard override — beats everything
    if place_name in PLACE_PREMIUM_OVERRIDES:
        chosen = PLACE_PREMIUM_OVERRIDES[place_name]

    # 2. Character hard lock — beats geo
    elif char in CHARACTER_PREMIUM_LOCK:
        chosen = CHARACTER_PREMIUM_LOCK[char]

    elif is_us:
        if char == "maya":
            chosen = None
        elif char == "isabella" and _is_city_place(place):
            chosen = _isabella_city_premium()
        else:
            geo = _us_geo_premium(place)
            if geo is not _GEO_NO_OPINION:
                chosen = geo
            elif char in _NIGHTLIFE_OK_CHARS | _NOIR_OK_CHARS and _night_place_ok(place):
                pref = CHARACTER_PREMIUM_PREFER.get(char) or ["sidewinder"]
                pool = [x for x in pref if x] or ["sidewinder"]
                if "sidewinder" not in pool:
                    pool = pool + ["sidewinder", "sidewinder", "sidewinder"]
                chosen = random.choice(pool)
            elif terrain in ["coastal", "lake"] and char in ["sofia", "ana", "lyra"]:
                chosen = None
            elif char in CHARACTER_PREMIUM_PREFER:
                chosen = random.choice(CHARACTER_PREMIUM_PREFER[char])
            else:
                chosen = "sidewinder"

    else:
        # EU: geo matrix first, then character prefer only if geo has no opinion
        geo = _eu_geo_premium(place)
        if geo is not _GEO_NO_OPINION:
            chosen = geo
        elif char in CHARACTER_PREMIUM_PREFER:
            chosen = random.choice(CHARACTER_PREMIUM_PREFER[char])
        else:
            chosen = None  # plain default

    chosen = _maybe_soft_eclipse(chosen, char, place)
    chosen = _prefer_eclipse_over_noir(chosen, place)
    chosen = _apply_night_noir_gate(chosen, place, char, is_us)
    return _finalize_premium_layer(chosen, place, is_us, character_key=char)


