def pick_secondary(terrain_type: str, place_type: str, country_code: str = "") -> str | None:
    """1 in 6 chance of including a secondary character. Returns prompt snippet or None."""
    if random.random() > (1/6):
        return None
    candidates = set()
    if terrain_type in SECONDARY_BY_TERRAIN:
        candidates.update(SECONDARY_BY_TERRAIN[terrain_type])
    pt = (place_type or "").lower()
    for key in SECONDARY_BY_PLACETYPE:
        if key in pt or pt in key:
            candidates.update(SECONDARY_BY_PLACETYPE[key])
    country_boosted = [k for k, v in SECONDARY_CHARACTERS.items()
                       if country_code in v.get("country_hint", [])]
    if country_boosted and random.random() < 0.4:
        key = random.choice(country_boosted)
    elif candidates:
        key = random.choice(list(candidates))
    else:
        key = random.choice(list(SECONDARY_CHARACTERS.keys()))
    char = SECONDARY_CHARACTERS[key]
    return f"""BACKGROUND FIGURE (do not focus, do not explain — ambient only):
{char['desc']}
Placement: {char['placement']}. Soft focus, never competing with main subject."""


def _row_is_active_human_cast(row: dict) -> bool:
    char = (row.get("character") or "").lower().strip()
    variant = (row.get("variant") or "").lower().strip()
    path = (row.get("storage_path") or "").lower()
    if not char or char in _MISSING_CAST_NON_HUMAN:
        return False
    if variant in ("goldie", "pexels", "arty", "chatgpt"):
        return False
    if path.startswith(("pexels/", "arty/", "chatgpt/")) or "/goldie/" in path:
        return False
    return variant in ("cast", "main") or path.startswith("cast/")


def place_ids_with_active_human_cast() -> set[str]:
    """Live DB: place_ids that already have ≥1 active human cast hero."""
    has_human: set[str] = set()
    start = 0
    while True:
        rows = (
            supabase.table("place_hero_images")
            .select("place_id,character,variant,storage_path")
            .eq("is_active", True)
            .range(start, start + 999)
            .execute()
            .data
            or []
        )
        if not rows:
            break
        for r in rows:
            if _row_is_active_human_cast(r):
                has_human.add(r["place_id"])
        if len(rows) < 1000:
            break
        start += 1000
    return has_human


def _local_cast_chars_sorted() -> list[str]:
    return sorted(
        (c for c in CAST if c not in _MISSING_CAST_NON_HUMAN),
        key=len,
        reverse=True,
    )


def _local_cast_files_by_slug() -> dict[str, list[str]]:
    """slug → character once per local cast webp (main/arrival/activity/exploit/farshot/…).

    Used by sparse-cast batch so a dry-run set of 5 is not treated as n=1 forever.
    """
    if not OUTPUT_DIR.is_dir():
        return {}
    chars = _local_cast_chars_sorted()
    shot_tok = (
        "_main", "_arrival", "_activity_", "_exploit_", "_farshot",
        "_cinematic_", "_dayhike", "_scenic", "_boost",
    )
    found: dict[str, list[str]] = {}
    for path in OUTPUT_DIR.glob("*.webp"):
        base = path.stem.lower()
        if any(tok in base for tok in ("_pexels", "_goldie", "_arty", "_chatgpt")):
            continue
        if not any(tok in base for tok in shot_tok):
            continue
        for char in chars:
            slug_end = base.find(f"_{char}_")
            if slug_end <= 0:
                continue
            slug = base[:slug_end]
            found.setdefault(slug, []).append(char)
            break
    return found


def _local_cast_mains_by_slug() -> dict[str, list[str]]:
    """slug → character keys with local cast *_main*.webp in ~/sunnomad_output (dry-run done)."""
    if not OUTPUT_DIR.is_dir():
        return {}
    chars = _local_cast_chars_sorted()
    found: dict[str, list[str]] = {}
    for path in OUTPUT_DIR.glob("*.webp"):
        base = path.stem.lower()
        if "_activity_" in base or "_arrival" in base or "_exploit_" in base:
            continue
        if not re.search(r"_main(?:_\d+)?$", base):
            continue
        if any(tok in base for tok in ("_pexels", "_goldie", "_arty", "_chatgpt")):
            continue
        for char in chars:
            slug_end = base.find(f"_{char}_")
            if slug_end <= 0:
                continue
            slug = base[:slug_end]
            found.setdefault(slug, []).append(char)
            break
    return found


def _local_cast_main_slugs() -> set[str]:
    """place_cc prefixes in ~/sunnomad_output that already have a cast *_main*.webp (dry-run done)."""
    return set(_local_cast_mains_by_slug())


def _place_file_slugs(place: dict) -> set[str]:
    """Slugs that may appear on local/storage filenames for this place."""
    slugs: set[str] = set()
    if place.get("image_slug"):
        slugs.add(place["image_slug"])
    cc = place.get("country_code")
    if place.get("name_en") and cc:
        try:
            slugs.add(_image_file_slug(place))
        except (KeyError, TypeError, AttributeError):
            pass
    # Legacy: before ı→i fold, "Plajı" became "plaj" (kaputas_plaj_tr vs kaputas_plaji_tr)
    name = place.get("name_en") or ""
    if "ı" in name or "İ" in name:
        for s in list(slugs):
            m = re.match(r"^(.+)i_([a-z]{2})$", s)
            if m:
                slugs.add(f"{m.group(1)}_{m.group(2)}")
    return slugs


def place_ids_with_local_cast_main() -> set[str]:
    """Places that already have cast main files locally (even if not synced to DB)."""
    local_slugs = _local_cast_main_slugs()
    if not local_slugs:
        return set()
    # image_slug lookup; also try plaji↔plaj so legacy TR filenames still resolve
    lookup = set(local_slugs)
    for s in list(local_slugs):
        m = re.match(r"^(.+)i_([a-z]{2})$", s)
        if m:
            lookup.add(f"{m.group(1)}_{m.group(2)}")
        m2 = re.match(r"^(.+)_([a-z]{2})$", s)
        if m2 and not m2.group(1).endswith("i"):
            lookup.add(f"{m2.group(1)}i_{m2.group(2)}")
    has: set[str] = set()
    resolved_locals: set[str] = set()
    slugs = sorted(lookup)
    for i in range(0, len(slugs), 80):
        chunk = slugs[i : i + 80]
        rows = (
            supabase.table("places")
            .select("id,name_en,country_code,image_slug")
            .in_("image_slug", chunk)
            .execute()
            .data
            or []
        )
        for p in rows:
            hit = _place_file_slugs(p) & local_slugs
            if hit:
                has.add(p["id"])
                resolved_locals |= hit
    # Null/missing image_slug (e.g. Elea Beach) — match computed place_cc slug by country
    unmatched = local_slugs - resolved_locals
    if unmatched:
        ccs: set[str] = set()
        for s in unmatched:
            m = re.match(r"^(.+)_([a-z]{2})$", s)
            if m:
                ccs.add(m.group(2).upper())
                ccs.add(m.group(2).lower())
        cc_list = sorted(ccs)
        for i in range(0, len(cc_list), 40):
            chunk = cc_list[i : i + 40]
            rows = (
                supabase.table("places")
                .select("id,name_en,country_code,image_slug")
                .in_("country_code", chunk)
                .execute()
                .data
                or []
            )
            for p in rows:
                hit = _place_file_slugs(p) & unmatched
                if hit:
                    has.add(p["id"])
                    resolved_locals |= hit
    return has


def place_has_local_cast_main(place: dict, local_slugs: set[str] | None = None) -> bool:
    """True if ~/sunnomad_output already has a cast main for this place (incl. null image_slug)."""
    if local_slugs is None:
        local_slugs = _local_cast_main_slugs()
    return bool(_place_file_slugs(place) & local_slugs)


def place_ids_already_have_cast() -> set[str]:
    """DB active human cast ∪ local cast mains — what --missing-cast / --safe should skip."""
    db = place_ids_with_active_human_cast()
    local = place_ids_with_local_cast_main()
    extra = local - db
    if extra:
        print(f"  ⏭️  {len(extra)} places skipped — local cast main in ~/sunnomad_output (not yet in DB)")
    return db | local


def fetch_missing_cast_place_ids(limit: int, offset: int = 0, eu_override: bool = False, us_override: bool = False) -> list[str]:
    """Top places by attractiveness with no cast yet (DB active human ∪ local mains). LatAm ex-MX skipped."""
    has_human = place_ids_with_active_human_cast()
    local_slugs = _local_cast_main_slugs()
    skip_names = set(BATCH_EXCLUDE_PLACE_NAMES) | set(GOLDIE_ONLY_PLACE_NAMES)
    query = (
        supabase.table("places")
        .select("id,name_en,country_code,state_name,attractiveness_score,image_slug")
        .eq("is_active", True)
        .order("attractiveness_score", desc=True)
        .limit(max(800, (offset + limit) * 20))
    )
    if eu_override and not us_override:
        query = query.not_.in_("country_code", list(AMERICAS_CODES))
    elif us_override and not eu_override:
        query = query.in_("country_code", list(AMERICAS_CODES))
    places = query.execute().data or []
    kept: list[str] = []
    skipped = 0
    local_skips = 0
    for p in places:
        cc = (p.get("country_code") or "").upper()
        if cc in LATAM_BATCH_EXCLUDE:
            continue
        if p.get("name_en") in skip_names:
            continue
        if p["id"] in has_human:
            continue
        # Computed slug match — works when image_slug is null (Elea Beach etc.)
        if place_has_local_cast_main(p, local_slugs):
            local_skips += 1
            continue
        if skipped < offset:
            skipped += 1
            continue
        kept.append(p["id"])
        print(f"  {len(kept):2}. {p.get('attractiveness_score', '?'):>3} {cc:2} {p.get('name_en')}")
        if len(kept) >= limit:
            break
    if local_skips:
        print(f"  ⏭️  {local_skips} places skipped — local cast main in ~/sunnomad_output")
    print(f"  📡 --missing-cast: {len(kept)} places (no DB cast, no local main)")
    return kept


def run_pipeline(limit=50, offset=0, dry_run=False, no_review=False, character_override=None, exploit=False, exploit_only=False, expression_override=None, time_override=None, wet_override=None, no_auto_premium=False,
                 goldie=False, goldie_only=False, multi_char=False, road_identity=False,
                 only_ids=None, exclude_ids=None, noir_mode=False, prestige_mode=False, nightlife_mode=False, viper_mode=False, maxpower_mode=False, outfit_override=None, eclipse_mode=False, sidewinder_mode=False, continental_mode=False, no_boost=False, outfit_light=None, activity=False, activity_key=None, exploit_key=None, premium_only=False, eu_override=False, us_override=False, activity_only=False, friend_char=None, cinematic_key=None,
                 exploit_all=False, cinematic_all=False, activity_all=False, specials_only=False, safe_mode=False, place_name_filter=None, dayhike_only=False, main_only=False, arrival_only=False, pick_char: bool = False):
    query = supabase.table("places").select(PLACE_ROW_SELECT).eq(
        "is_active", True
    ).order("attractiveness_score", desc=True)
    if eu_override and not us_override:
        query = query.not_.in_("country_code", list(AMERICAS_CODES))
    elif us_override and not eu_override:
        query = query.in_("country_code", list(AMERICAS_CODES))
    if only_ids:
        query = query.in_("id", only_ids)
    elif offset:
        query = query.range(offset, offset + limit - 1)
    elif character_override and not place_name_filter:
        # Wider pool — goldie-only showcase places must not eat limit=1 (Dublin → dog)
        query = query.limit(max(limit * 25, 50))
    else:
        query = query.limit(limit)
    if exclude_ids:
        query = query.not_.in_("id", exclude_ids)
    if place_name_filter:
        _pref = _ascii_fold(place_name_filter).strip()
        if len(_pref) >= 3:
            _name_pat = _pref[: min(len(_pref), 12)]
            _slug_pat = _place_filter_slug(place_name_filter)[:40]
            # Tekirdağ etc.: ascii needle fails name_en ilike — also hit image_slug
            query = query.or_(
                f"name_en.ilike.%{_name_pat}%,image_slug.ilike.%{_slug_pat}%"
            )
    result = query.execute()
    places = [
        p for p in (result.data or [])
        if p.get("name_en") not in BATCH_EXCLUDE_PLACE_NAMES
        and (not place_name_filter or _place_filter_matches(place_name_filter, p))
        and not (character_override and p.get("name_en") in GOLDIE_ONLY_PLACE_NAMES)
    ]
    if character_override and not place_name_filter and not only_ids:
        places = places[:limit]
    if only_ids:
        _order = {pid: i for i, pid in enumerate(only_ids)}
        places.sort(key=lambda p: _order.get(p["id"], 10_000))
    if BATCH_EXCLUDE_PLACE_NAMES and len(places) < len(result.data or []):
        print(f"  ⏭️  Batch exclude: {', '.join(sorted(BATCH_EXCLUDE_PLACE_NAMES))}")
    # Character sets: arrival on by default (fill toward 5) unless a single-shot focus flag
    _pipeline_road_identity = arrival_only or road_identity or (
        bool(character_override)
        and not activity_only
        and not main_only
        and not dayhike_only
        and not exploit_only
        and not cinematic_key
        and not specials_only
    )
    print(f"Pipeline: {len(places)} places | offset={offset} | dry_run={dry_run} | exploit={exploit} | activity={activity} | road_identity={_pipeline_road_identity}{' | 🐕 GOLDIE ONLY' if goldie_only else ''}{' | 🥾 DAYHIKE ONLY' if dayhike_only else ''}{' | 🚗 ARRIVAL ONLY' if arrival_only else ''}{' | ⛨ SAFE MODE' if safe_mode else ''}")

    ok, failed = 0, 0
    try:
        for i, place in enumerate(places):
            print(f"\n[{i+1}/{len(places)}]", end="")
            try:
                # Re-check every place (list is stale if another batch runs in parallel).
                # Skip only for untargeted --safe/--missing-cast sweeps — never when
                # --only-ids / --place / --character (targeted regen) is set.
                _targeted_regen = bool(character_override or place_name_filter or only_ids)
                if safe_mode and not _targeted_regen and place_has_local_cast_main(place):
                    print(
                        f"  ⏭️  skip {place.get('name_en','')} — local cast main already exists "
                        f"(concurrent/prior batch)"
                    )
                    continue
                _base = get_base_layer(place["country_code"])
                # us and eu are mutually exclusive — explicit override wins, us takes priority if both set
                if us_override and eu_override:
                    _us, _eu = True, False  # --us wins over --eu if both passed
                elif us_override:
                    _us, _eu = True, False
                elif eu_override:
                    _us, _eu = False, True
                else:
                    _us = _base == "us"
                    _eu = _base == "eu"
                if goldie_only:
                    _char = None
                elif character_override:
                    _char = character_override
                elif pick_char:
                    _char = prompt_pick_character(place, n=5)
                else:
                    _char = select_character(
                        place["country_code"], place.get("terrain_type",""), place.get("place_type",""),
                        place.get("name_en",""), place=place,
                    )
                if character_override == "valentina" and not valentina_allowed(place):
                    print(f"  ⏭️  Valentina skipped — not allowed here ({place.get('name_en','')})")
                    continue
                if character_override:
                    global _nature_wildcard_char
                    if (is_nature_place(place)
                            and character_override in NATURE_WILDCARD_CHARS
                            and character_override not in NATURE_WILDCARD_NO_DISCOMFORT):
                        _nature_wildcard_char = character_override
                    else:
                        _nature_wildcard_char = None

                _place_goldie_only = goldie_only or is_goldie_only_place(place)
                if _place_goldie_only and character_override:
                    print(
                        f"  ⏭️  skip {place.get('name_en','')} — goldie-only showcase "
                        f"(not for --character {character_override})"
                    )
                    continue
                if _place_goldie_only and not (activity_key or activity_only):
                    process_place(place, dry_run=dry_run, goldie_only=True,
                                  no_review=no_review, outfit_override=outfit_override,
                                  us_mode=_us, eu_mode=_eu)
                    ok += 1
                    continue

                _score = place.get("attractiveness_score", 0)
                _manual_premium = any([noir_mode, prestige_mode, nightlife_mode, viper_mode, maxpower_mode, eclipse_mode, sidewinder_mode, continental_mode])

                if premium_only:
                    # Skip base — run only premium layer with auto char/layer/outfit
                    _premium = pick_premium_layer(place, _char, void_energy=7)
                    if not _premium and not is_nature_place(place):
                        _premium = "eclipse" if not _us else "sidewinder"
                    elif not _premium and is_nature_place(place):
                        _premium = "sidewinder" if _us else None
                    _prem_outfit = pick_premium_outfit_light(place, _char, _premium) if _premium else None
                    print(f"  ✨ Premium-only: {_premium} | char={_char} | outfit={_prem_outfit}")
                    _pm = {k: _premium == v for k, v in [
                        ("noir_mode","noir"), ("prestige_mode","prestige"), ("nightlife_mode","nightlife"),
                        ("viper_mode","viper"), ("maxpower_mode","maxpower"), ("eclipse_mode","eclipse"), ("sidewinder_mode","sidewinder"),
                        ("continental_mode","continental"),
                    ]} if _premium else {}
                    _pm = suppress_urban_premium_for_place(place, **_pm)
                    process_place(place, dry_run=dry_run, exploit=exploit, exploit_only=exploit_only,
                                  goldie=False, goldie_only=False, multi_char=False, road_identity=True,
                                  no_review=no_review, character_override=_char,
                                  no_boost=True, outfit_light=_prem_outfit,
                                  us_mode=_us, eu_mode=_eu, activity=True, activity_key=None,
                                  exploit_key=exploit_key, **_pm)
                else:
                    # Standard run: premium baked into main; activity + arrival on unless --no-activities / focus flags
                    _auto_premium_raw = None
                    if not _manual_premium and not no_auto_premium and _score >= 85:
                        _auto_premium_raw = pick_premium_layer(place, _char, void_energy=6)  # 6 = reasonable default
                        _is_us_place = place["country_code"] in AMERICAS_CODES
                        # pick_premium_layer already finalizes; re-run with char so Isabella city prestige survives
                        _auto_premium = _finalize_premium_layer(
                            _auto_premium_raw, place, _is_us_place, character_key=_char,
                        )
                        _prem_outfit = pick_premium_outfit_light(place, _char, _auto_premium or _auto_premium_raw) if (_auto_premium or _auto_premium_raw) else outfit_light
                    else:
                        _auto_premium = None
                        _prem_outfit = outfit_light

                    _pm = {}
                    if _auto_premium:
                        print(f"  ✨ Premium baked in: {_auto_premium} | char={_char}")
                    elif _auto_premium_raw:
                        print(f"  ⏭️  Premium suppressed for outdoor place (was {_auto_premium_raw}) | char={_char}")
                    if _auto_premium:
                        _pm = {k: _auto_premium == v for k, v in [
                            ("noir_mode","noir"), ("prestige_mode","prestige"), ("nightlife_mode","nightlife"),
                            ("viper_mode","viper"), ("maxpower_mode","maxpower"), ("eclipse_mode","eclipse"), ("sidewinder_mode","sidewinder"),
                            ("continental_mode","continental"),
                        ]}

                    # Merge manual layer flags on top
                    if noir_mode:      _pm["noir_mode"] = True
                    if prestige_mode:  _pm["prestige_mode"] = True
                    if nightlife_mode: _pm["nightlife_mode"] = True
                    if viper_mode:     _pm["viper_mode"] = True
                    if maxpower_mode:  _pm["maxpower_mode"] = True
                    if eclipse_mode:   _pm["eclipse_mode"] = True
                    if sidewinder_mode: _pm["sidewinder_mode"] = True
                    if continental_mode: _pm["continental_mode"] = True

                    _pm = suppress_urban_premium_for_place(place, **_pm)

                    if not exploit_all and not cinematic_all and not activity_all:
                        process_place(place, dry_run=dry_run, exploit=exploit, exploit_only=exploit_only,
                                      goldie=goldie, goldie_only=goldie_only, multi_char=multi_char,
                                      road_identity=_pipeline_road_identity,
                                      no_review=no_review, character_override=character_override or _char,
                                      outfit_override=outfit_override, no_boost=no_boost, outfit_light=_prem_outfit,
                                      us_mode=_us, eu_mode=_eu,
                                      activity=activity,
                                      activity_key=activity_key, exploit_key=exploit_key,
                                      activity_only=activity_only, dayhike_only=dayhike_only, main_only=main_only,
                                      arrival_only=arrival_only,
                                      expression_override=expression_override,
                                      time_override=time_override, wet_override=wet_override, friend_char=friend_char,
                                      cinematic_key=cinematic_key, safe_mode=safe_mode, **_pm)

                    if exploit_all:
                        _keys = EXPLOIT_REPERTOIRE.get(_char, [])
                        print(f"  🔁 exploit-all: {len(_keys)} keys for {_char}")
                        for _k in _keys:
                            try:
                                process_place(place, dry_run=dry_run, exploit=True, exploit_only=True,
                                              no_review=no_review, character_override=_char,
                                              us_mode=_us, eu_mode=_eu, exploit_key=_k, **_pm)
                            except Exception as _e:
                                print(f"    ❌ {_k}: {_e}")

                    if cinematic_all:
                        _ckeys = [k for k, chars in CINEMATIC_REPERTOIRE.items() if _char in chars]
                        print(f"  🔁 cinematic-all: {len(_ckeys)} keys for {_char}")
                        for _k in _ckeys:
                            try:
                                process_place(place, dry_run=dry_run, exploit=False, exploit_only=False,
                                              no_review=no_review, character_override=_char,
                                              us_mode=_us, eu_mode=_eu, cinematic_key=_k,
                                              activity=False, road_identity=False, **_pm)
                            except Exception as _e:
                                print(f"    ❌ {_k}: {_e}")

                    if activity_all:
                        _terrain = place.get("terrain_type", "")
                        _pt = (place.get("place_type") or "").lower()
                        _akeys = pick_activity(_char, _terrain, _pt, n=99, place_name=_place_name_en(place), place=place)
                        print(f"  🔁 activity-all: {len(_akeys)} keys for {_char}")
                        for _k in _akeys:
                            try:
                                process_place(place, dry_run=dry_run, exploit=False, exploit_only=False,
                                              no_review=no_review, character_override=_char,
                                              us_mode=_us, eu_mode=_eu, activity=True, activity_key=_k,
                                              activity_only=True, road_identity=False, **_pm)
                            except Exception as _e:
                                print(f"    ❌ {_k}: {_e}")

                    if specials_only:
                        _specials = CHAR_SPECIALS.get(_char, [])
                        if not _specials:
                            print(f"  ⏭️  No char specials defined for {_char}")
                        else:
                            print(f"  ⭐ specials-only: {len(_specials)} for {_char}")
                            for _stype, _sk in _specials:
                                try:
                                    if _stype == "exploit":
                                        process_place(place, dry_run=dry_run, exploit=True, exploit_only=True,
                                                      no_review=no_review, character_override=_char,
                                                      us_mode=_us, eu_mode=_eu, exploit_key=_sk, **_pm)
                                    elif _stype == "cinematic":
                                        process_place(place, dry_run=dry_run, exploit=False, exploit_only=False,
                                                      no_review=no_review, character_override=_char,
                                                      us_mode=_us, eu_mode=_eu, cinematic_key=_sk,
                                                      activity=False, road_identity=False, **_pm)
                                    elif _stype == "activity":
                                        process_place(place, dry_run=dry_run, exploit=False, exploit_only=False,
                                                      no_review=no_review, character_override=_char,
                                                      us_mode=_us, eu_mode=_eu, activity=True, activity_key=_sk,
                                                      activity_only=True, road_identity=False, **_pm)
                                except Exception as _e:
                                    print(f"    ❌ {_stype}/{_sk}: {_e}")

                ok += 1
            except Exception as e:
                print(f"\n  ❌ {e}")
                failed += 1
    except KeyboardInterrupt:
        print("\n⚠️  Interrupted — cost so far:")
    finally:
        print(f"\n{'='*50}")
        print(f"✅ {ok} done  ❌ {failed} failed")
        print(_cost_summary())


def run_free_shot(
    prompt: str,
    *,
    character: str | None = None,
    landscape: bool = False,
    output_stem: str | None = None,
    use_canonical: bool = True,
) -> Path:
    """One-off image from raw prompt — no place, no pipeline."""
    OUTPUT_DIR.mkdir(exist_ok=True)
    p = prompt.strip()
    _nylon = get_nylon_seam_lock(character or "", prompt_text=p)
    if _nylon:
        p += "\n\n" + _nylon
    if landscape:
        p += "\n\nMANDATORY: horizontal 16:9 landscape. Wide cinematic frame. NOT portrait. NOT vertical."
    if character == "goldie":
        p += (
            "\n\nSUBJECT: Goldie — smooth-coated reddish-tan Podenco-Terrier mix, "
            "rose/folded ears, red collar. Preserve identity exactly."
        )
    ref = None
    if character and use_canonical and not landscape:
        ref = load_canonical(character)
        _anchor = CHARACTER_BODY_ANCHORS.get(character, "")
        p = (
            "FREE SHOT — NEW PHOTOGRAPH (NON-NEGOTIABLE):\n"
            "Reference image = FACE / IDENTITY / body type only.\n"
            "Do NOT copy the reference pose, crop, background, lighting setup, camera angle, or wardrobe framing.\n"
            "Do NOT output a near-duplicate of the canonical. Invent the scene described below as a fresh shot.\n"
            f"Character: {character}."
            + (f" Body cue: {_anchor}\n" if _anchor else "\n")
            + "Execute this scene:\n\n"
            + p
        )
        print(f"  🆔 free-shot: canonical={character} as identity only (not pose/copy)")
    elif character and not use_canonical:
        print(f"  🆔 free-shot: no canonical — text identity for {character}")
    raw = generate_image_safety_retry(
        p, reference_bytes=ref, landscape=landscape, free_shot=True,
    )
    stem = output_stem or "free_shot"
    tag = "_16x9" if landscape else ""
    out = OUTPUT_DIR / f"{stem}{tag}.webp"
    out.write_bytes(convert_to_webp(raw, landscape=landscape))
    dims = f"{LANDSCAPE_TARGET_W}x{LANDSCAPE_TARGET_H}" if landscape else f"{TARGET_W}x{TARGET_H}"
    print(f"  💾 {out} ({dims})")
    return out


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--limit", type=int, default=50)
    parser.add_argument("--offset", type=int, default=0)
    parser.add_argument("--dry-run", action="store_true", default=True)
    parser.add_argument("--no-dry-run", dest="dry_run", action="store_false")
    parser.add_argument(
        "--safe",
        action="store_true",
        help="Safe mode: no exploits, curated activity pool, anti-distortion prompt. "
        "Also selects places via live DB (no active human cast); ignores stale --only-ids unless targeted/regen flags.",
    )
    parser.add_argument("--no-review", action="store_true")
    parser.add_argument("--exploit", action="store_true")
    parser.add_argument("--exploit-only", action="store_true")
